head.script:
/**/
(function(){
  try{
    var saved=localStorage.getItem('techit-theme');
    if(saved === 'dark' || (!saved && window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches)) {
      document.documentElement.setAttribute('data-theme', 'dark');
    }
  }catch(e){}
})();
/**/

head.b:skin:
/* ==========================================================================
   TechIT — LUXURY EDITION  |  Premium Blogger Theme  |  by Banti Kevat
   Tech in Hindi · React · JavaScript · AI Tools · Coding
   ========================================================================== */

/* ----------------------------- 1. TOKENS ------------------------------- */
:root{
  --primary:#06b6d4;
  --primary-d:#0891b2;
  --secondary:#2563eb;
  --secondary-d:#1d4ed8;
  --accent:#8b5cf6;
  --navy:#0d1b2a;
  --navy-2:#13263c;
  --grad:linear-gradient(135deg,#06b6d4 0%,#2563eb 55%,#8b5cf6 110%);
  --grad-2:linear-gradient(135deg,#2563eb,#06b6d4);
  --grad-soft:linear-gradient(135deg,rgba(6,182,212,.12),rgba(37,99,235,.12));

  --bg:#eef2f8;
  --bg-soft:#f6f8fc;
  --card:#ffffff;
  --text:#16213a;
  --text-soft:#3b4a64;
  --muted:#7585a0;
  --line:#e4e9f2;
  --line-2:#eef1f7;

  --radius:18px;
  --radius-sm:12px;
  --radius-lg:26px;
  --shadow-sm:0 2px 10px rgba(13,27,42,.06);
  --shadow:0 8px 30px rgba(13,27,42,.09);
  --shadow-lg:0 18px 50px rgba(13,27,42,.14);
  --glow:0 8px 28px rgba(6,182,212,.40);
  --maxw:1240px;
  --header-h:74px;
  --ease:cubic-bezier(.4,0,.2,1);
  --font:'Inter',system-ui,-apple-system,'Segoe UI',Roboto,sans-serif;
  --font-head:'Sora','Inter',sans-serif;
  --font-mono:'JetBrains Mono',monospace;
}

/* ----------------------------- DARK MODE ------------------------------- */
html[data-theme='dark']{
  --bg:#0a1320;
  --bg-soft:#0f1d30;
  --card:#13243a;
  --text:#e8eef8;
  --text-soft:#b8c4d8;
  --muted:#8195b2;
  --line:#1f3550;
  --line-2:#1a2c44;
  --shadow-sm:0 2px 10px rgba(0,0,0,.35);
  --shadow:0 8px 30px rgba(0,0,0,.45);
  --shadow-lg:0 18px 50px rgba(0,0,0,.55);
}

/* ----------------------------- 2. RESET -------------------------------- */
*{box-sizing:border-box;margin:0;padding:0}
html{scroll-behavior:smooth;-webkit-text-size-adjust:100%;scroll-padding-top:90px;overflow-x:hidden}
body{
  font-family:var(--font);background:var(--bg);color:var(--text);
  line-height:1.7;font-size:16px;overflow-x:hidden;transition:background .4s var(--ease),color .4s var(--ease);
  -webkit-font-smoothing:antialiased;
}
img{max-width:100%;height:auto;display:block}
svg{display:block}
a{color:var(--secondary);text-decoration:none;transition:.25s var(--ease)}
a:hover{color:var(--primary)}
ul{list-style:none}
button{font-family:inherit;cursor:pointer;border:0;background:none}
h1,h2,h3,h4,h5{font-family:var(--font-head);font-weight:700;line-height:1.28;color:var(--text);letter-spacing:-.01em}
.wrap{max-width:var(--maxw);margin:0 auto;padding:0 18px}
.sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0,0,0,0)}
::selection{background:var(--primary);color:#fff}
::-webkit-scrollbar{width:11px;height:11px}
::-webkit-scrollbar-track{background:var(--bg-soft)}
::-webkit-scrollbar-thumb{background:var(--grad);border-radius:10px;border:2px solid var(--bg-soft)}

/* ----------------------------- 3. PRELOADER ---------------------------- */
#preloader{position:fixed;inset:0;z-index:9999;background:var(--navy);display:flex;align-items:center;justify-content:center;flex-direction:column;gap:24px;transition:opacity .5s,visibility .5s;padding:20px}
#preloader.done{opacity:0;visibility:hidden}
.pre-logo-wrapper{width:100%;max-width:240px;aspect-ratio:1/1;display:flex;align-items:center;justify-content:center;position:relative}
.pre-logo-svg{width:100%;height:100%;animation:pulse 1.8s var(--ease) infinite}
.pre-bar{width:140px;height:4px;border-radius:4px;background:rgba(255,255,255,.15);overflow:hidden;flex-shrink:0}
.pre-bar span{display:block;height:100%;width:40%;background:var(--grad);border-radius:4px;animation:load 1.1s var(--ease) infinite}
@keyframes pulse{0%,100%{transform:scale(1)}50%{transform:scale(1.06)}}
@keyframes load{0%{margin-left:-40%}100%{margin-left:100%}}

/* ----------------------------- 4. READING PROGRESS --------------------- */
#progress{position:fixed;top:0;left:0;height:3px;width:0;background:var(--grad);z-index:9000;transition:width .1s linear}

/* ----------------------------- 5. HEADER ------------------------------- */
.site-header{position:sticky;top:0;z-index:2000}
.topbar{background:var(--navy);color:#cbd5e1;font-size:12.5px;border-bottom:1px solid rgba(255,255,255,.06)}
.topbar .wrap{display:flex;justify-content:space-between;align-items:center;height:36px;gap:10px}
.topbar .tb-left i{color:var(--primary);margin-right:6px}
.topbar a{color:#cbd5e1}
.topbar a:hover{color:#fff}
.tb-social a{margin-left:13px;font-size:14px}

.header-main{background:rgba(255,255,255,.82);backdrop-filter:saturate(180%) blur(16px);-webkit-backdrop-filter:saturate(180%) blur(16px);border-bottom:1px solid var(--line);box-shadow:var(--shadow-sm);transition:.3s}
html[data-theme='dark'] .header-main{background:rgba(13,27,42,.82)}
.header-main.shrink{box-shadow:var(--shadow)}
.header-main .wrap{display:flex;align-items:center;justify-content:space-between;gap:18px;min-height:var(--header-h)}

.brand{display:flex;align-items:center;gap:13px;flex-shrink:0}
.brand .logo-mark{width:48px;height:48px;border-radius:14px;background:var(--navy-2);display:flex;align-items:center;justify-content:center;box-shadow:var(--glow);position:relative;overflow:hidden;padding:5px}
.brand .logo-mark::after{content:"";position:absolute;inset:0;background:linear-gradient(120deg,transparent 30%,rgba(255,255,255,.4),transparent 70%);transform:translateX(-100%);animation:shine 3.5s infinite}
@keyframes shine{0%,60%{transform:translateX(-100%)}100%{transform:translateX(100%)}}
.brand .logo-text b{display:block;font-family:var(--font-head);font-size:23px;font-weight:800;color:var(--text);letter-spacing:.3px;line-height:1}
.brand .logo-text span{font-size:10.5px;letter-spacing:3px;color:var(--primary);text-transform:uppercase;font-weight:600}

/* ---- NAV ---- */
nav.main-nav>ul{display:flex;align-items:center;gap:2px}
nav.main-nav>ul>li{position:relative}
nav.main-nav a{color:var(--text-soft);font-weight:600;font-size:14.5px;padding:11px 15px;border-radius:11px;display:flex;align-items:center;gap:6px;position:relative}
nav.main-nav>ul>li>a:hover{color:var(--primary);background:var(--grad-soft)}
nav.main-nav>ul>li>a::before{content:"";position:absolute;left:50%;bottom:5px;width:0;height:2px;background:var(--grad);border-radius:2px;transform:translateX(-50%);transition:width .25s}
nav.main-nav>ul>li:hover>a::before{width:22px}
.sub-ic{font-size:9px;transition:.25s}
.submenu{position:absolute;top:calc(100% + 8px);left:0;min-width:216px;background:var(--card);border:1px solid var(--line);border-radius:14px;box-shadow:var(--shadow-lg);padding:9px;opacity:0;visibility:hidden;transform:translateY(12px);transition:.28s var(--ease);border-top:3px solid var(--primary)}
nav.main-nav li.has-sub:hover>.submenu{opacity:1;visibility:visible;transform:translateY(0)}
nav.main-nav li.has-sub:hover .sub-ic{transform:rotate(180deg)}
.submenu li a{padding:10px 13px;font-size:14px;border-radius:9px;color:var(--text-soft);font-weight:500}
.submenu li a:hover{background:var(--grad-soft);color:var(--primary);padding-left:18px}
.submenu li a i{color:var(--primary);font-size:12px;width:16px}

.nav-tools{display:flex;align-items:center;gap:8px;flex-shrink:0}
.icon-btn{width:44px;height:44px;border-radius:12px;background:var(--bg-soft);color:var(--text);border:1px solid var(--line);display:flex;align-items:center;justify-content:center;font-size:16px;transition:.25s}
.icon-btn:hover{background:var(--grad);color:#fff;border-color:transparent;transform:translateY(-2px)}
#themeToggle .fa-sun{display:none}
html[data-theme='dark'] #themeToggle .fa-sun{display:block}
html[data-theme='dark'] #themeToggle .fa-moon{display:none}
.menu-toggle{display:none}

/* ----------------------------- 6. HERO BANNER -------------------------- */
.hero{position:relative;overflow:hidden;background:var(--navy);color:#fff;padding:64px 0 72px;margin-bottom:8px}
.hero::before{content:"";position:absolute;top:-30%;right:-10%;width:55%;height:160%;background:radial-gradient(circle,rgba(6,182,212,.28),transparent 60%);filter:blur(20px)}
.hero::after{content:"";position:absolute;bottom:-40%;left:-10%;width:55%;height:160%;background:radial-gradient(circle,rgba(139,92,246,.22),transparent 60%);filter:blur(20px)}
.hero .wrap{position:relative;z-index:2;display:grid;grid-template-columns:1.1fr .9fr;gap:40px;align-items:center}
.hero-badge{display:inline-flex;align-items:center;gap:8px;background:rgba(255,255,255,.1);border:1px solid rgba(255,255,255,.18);padding:7px 16px;border-radius:50px;font-size:13px;font-weight:600;margin-bottom:20px;color:#a5f3fc}
.hero-badge .dot{width:8px;height:8px;border-radius:50%;background:#22c55e;box-shadow:0 0 0 4px rgba(34,197,94,.25);animation:blink 1.6s infinite}
@keyframes blink{0%,100%{opacity:1}50%{opacity:.4}}
.hero h1{font-size:46px;line-height:1.15;color:#fff;margin-bottom:18px}
.hero h1 .g{background:var(--grad);-webkit-background-clip:text;background-clip:text;-webkit-text-fill-color:transparent}
.hero p{font-size:17px;color:#cbd5e1;max-width:520px;margin-bottom:28px}
.hero-cta{display:flex;gap:14px;flex-wrap:wrap}
.btn{display:inline-flex;align-items:center;gap:9px;font-weight:700;font-size:15px;padding:14px 26px;border-radius:14px;transition:.28s var(--ease)}
.btn-primary{background:var(--grad);color:#fff;box-shadow:var(--glow)}
.btn-primary:hover{color:#fff;transform:translateY(-3px);box-shadow:0 14px 36px rgba(6,182,212,.5)}
.btn-ghost{background:rgba(255,255,255,.08);color:#fff;border:1px solid rgba(255,255,255,.2)}
.btn-ghost:hover{background:rgba(255,255,255,.16);color:#fff}
.hero-stats{display:flex;gap:30px;margin-top:34px}
.hero-stats div b{display:block;font-family:var(--font-head);font-size:26px;color:#fff}
.hero-stats div span{font-size:12.5px;color:#94a3b8}
.hero-visual{position:relative;display:flex;align-items:center;justify-content:center}
.hero-card{background:rgba(255,255,255,.06);border:1px solid rgba(255,255,255,.14);border-radius:22px;padding:26px;width:100%;max-width:380px;backdrop-filter:blur(10px);box-shadow:var(--shadow-lg)}
.hero-code{font-family:var(--font-mono);font-size:13.5px;line-height:2;color:#e2e8f0}
.hero-code .k{color:#8b5cf6}.hero-code .s{color:#22d3ee}.hero-code .f{color:#60a5fa}.hero-code .c{color:#64748b}
.float-chip{position:absolute;background:var(--card);color:var(--text);border-radius:14px;padding:11px 16px;font-size:13px;font-weight:700;box-shadow:var(--shadow-lg);display:flex;align-items:center;gap:9px;animation:floaty 4s var(--ease) infinite}
.float-chip i{font-size:17px}
.float-chip.c1{top:6%;left:-4%;animation-delay:0s}
.float-chip.c2{bottom:8%;right:-6%;animation-delay:1.4s}
.float-chip.c1 i{color:#61dafb}.float-chip.c2 i{color:#22c55e}
@keyframes floaty{0%,100%{transform:translateY(0)}50%{transform:translateY(-14px)}}

/* ----------------------------- 7. CATEGORY STRIP ----------------------- */
.cat-strip{padding:42px 0 8px}
.cat-grid{display:grid;grid-template-columns:repeat(5,1fr);gap:16px}
.cat-card{background:var(--card);border:1px solid var(--line);border-radius:var(--radius);padding:24px 18px;text-align:center;transition:.3s var(--ease);position:relative;overflow:hidden}
.cat-card::before{content:"";position:absolute;inset:0;background:var(--grad);opacity:0;transition:.3s}
.cat-card>*{position:relative;z-index:1;transition:.3s}
.cat-card:hover{transform:translateY(-8px);box-shadow:var(--shadow-lg);border-color:transparent}
.cat-card:hover::before{opacity:1}
.cat-card:hover .cat-ic,.cat-card:hover b,.cat-card:hover small{color:#fff}
.cat-ic{width:56px;height:56px;margin:0 auto 14px;border-radius:16px;background:var(--grad-soft);color:var(--primary);display:flex;align-items:center;justify-content:center;font-size:24px;transition:.3s}
.cat-card:hover .cat-ic{background:rgba(255,255,255,.2)}
.cat-card b{display:block;font-family:var(--font-head);font-size:15.5px;color:var(--text);margin-bottom:3px}
.cat-card small{color:var(--muted);font-size:12px}

/* ----------------------------- 8. SECTION HEAD ------------------------- */
.content-area{padding:34px 0 30px}
.layout-grid{display:grid;grid-template-columns:1fr 330px;gap:36px;align-items:start}
.sec-head{display:flex;align-items:center;justify-content:space-between;margin:0 0 24px;gap:14px}
.sec-title{display:flex;align-items:center;gap:12px;font-size:23px;position:relative}
.sec-title .bar{width:6px;height:26px;border-radius:5px;background:var(--grad)}
.sec-title small{display:block;font-family:var(--font);font-size:12px;color:var(--muted);font-weight:500;letter-spacing:.5px;text-transform:uppercase;margin-top:2px}
.sec-link{font-size:13.5px;font-weight:700;color:var(--secondary);display:inline-flex;align-items:center;gap:7px}
.sec-link:hover{gap:11px;color:var(--primary)}

/* ----------------------------- 9. FEATURED HERO POSTS ------------------ */
.feat-grid{display:grid;grid-template-columns:1.5fr 1fr;gap:22px;margin-bottom:42px}
.feat-side{display:grid;grid-template-rows:repeat(2,1fr);gap:22px}
.feat-big,.feat-sm{position:relative;border-radius:var(--radius-lg);overflow:hidden;box-shadow:var(--shadow);min-height:230px;display:flex;align-items:flex-end}
.feat-big{min-height:484px}
.feat-big img,.feat-sm img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;transition:.6s var(--ease);z-index:0}
.feat-big:hover img,.feat-sm:hover img{transform:scale(1.07)}
.feat-overlay{position:absolute;inset:0;background:linear-gradient(to top,rgba(7,15,28,.92) 6%,rgba(7,15,28,.45) 45%,transparent 80%);z-index:1}
.feat-content{position:relative;z-index:2;padding:26px;width:100%}
.feat-sm .feat-content{padding:20px}
.feat-content .lbl{display:inline-block;background:var(--grad);color:#fff;font-size:11px;font-weight:700;padding:5px 13px;border-radius:50px;text-transform:uppercase;letter-spacing:.5px;margin-bottom:12px}
.feat-big h2{font-size:27px;line-height:1.45;margin-bottom:10px}
.feat-big h2 a{color:#fff}.feat-big h2 a:hover{color:#67e8f9}
.feat-sm h3{font-size:17px;line-height:1.45}
.feat-sm h3 a{color:#fff}.feat-sm h3 a:hover{color:#67e8f9}
.feat-meta{display:flex;gap:16px;color:#cbd5e1;font-size:12.5px;margin-top:8px}
.feat-meta i{color:#67e8f9;margin-right:5px}

/* ----------------------------- 10. POST CARDS -------------------------- */
.post-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:26px}
.p-card{background:var(--card);border-radius:var(--radius);overflow:hidden;box-shadow:var(--shadow-sm);border:1px solid var(--line);transition:.3s var(--ease);display:flex;flex-direction:column}
.p-card:hover{transform:translateY(-7px);box-shadow:var(--shadow-lg);border-color:rgba(6,182,212,.3)}
.p-thumb{position:relative;aspect-ratio:16/9;overflow:hidden;background:var(--bg-soft);display:block}
.p-thumb img{width:100%;height:100%;object-fit:cover;transition:.6s var(--ease)}
.p-card:hover .p-thumb img{transform:scale(1.08)}
.p-thumb::after{content:"";position:absolute;inset:0;background:linear-gradient(to top,rgba(13,27,42,.35),transparent 50%);opacity:0;transition:.3s}
.p-card:hover .p-thumb::after{opacity:1}
.p-label{position:absolute;top:13px;left:13px;background:var(--grad);color:#fff;font-size:10.5px;font-weight:700;padding:5px 13px;border-radius:50px;text-transform:uppercase;letter-spacing:.5px;box-shadow:var(--glow);z-index:2}
.p-read-time{position:absolute;bottom:13px;right:13px;background:rgba(13,27,42,.8);color:#fff;font-size:11px;font-weight:600;padding:4px 11px;border-radius:50px;z-index:2;backdrop-filter:blur(4px)}
.p-body{padding:20px;display:flex;flex-direction:column;flex:1}
.p-cat{font-size:12px;font-weight:700;color:var(--primary);text-transform:uppercase;letter-spacing:.5px;margin-bottom:9px}
.p-title{font-size:18.5px;margin-bottom:11px;line-height:1.5}
.p-title a{color:var(--text)}
.p-title a:hover{color:var(--secondary)}
.p-snippet{color:var(--text-soft);font-size:14.5px;margin-bottom:16px;flex:1}
.p-foot{display:flex;align-items:center;justify-content:space-between;border-top:1px solid var(--line-2);padding-top:14px}
.p-author{display:flex;align-items:center;gap:9px}
.p-author .av{width:34px;height:34px;border-radius:50%;background:var(--grad);color:#fff;display:flex;align-items:center;justify-content:center;font-size:14px;font-weight:700}
.p-author b{font-size:13px;color:var(--text);display:block;line-height:1.2}
.p-author span{font-size:11.5px;color:var(--muted)}
.p-foot .arr{width:36px;height:36px;border-radius:11px;background:var(--bg-soft);color:var(--primary);display:flex;align-items:center;justify-content:center;transition:.25s}
.p-card:hover .p-foot .arr{background:var(--grad);color:#fff}

/* ----------------------------- 11. PAGINATION -------------------------- */
.blog-pager,#blog-pager{text-align:center;margin:40px 0 6px;display:flex;justify-content:center;gap:12px;flex-wrap:wrap}
.blog-pager a,#blog-pager a,.pager-btn{display:inline-flex;align-items:center;gap:9px;background:var(--card);border:1px solid var(--line);color:var(--text);font-weight:700;font-size:14px;padding:13px 26px;border-radius:14px;box-shadow:var(--shadow-sm);transition:.25s}
.blog-pager a:hover,#blog-pager a:hover,.pager-btn:hover{background:var(--grad);color:#fff;border-color:transparent;transform:translateY(-2px);box-shadow:var(--glow)}

/* ----------------------------- 12. SINGLE POST ------------------------- */
.breadcrumb{display:flex;align-items:center;gap:9px;flex-wrap:wrap;font-size:13px;color:var(--muted);margin-bottom:20px}
.breadcrumb a{color:var(--text-soft);font-weight:500}
.breadcrumb a:hover{color:var(--primary)}
.breadcrumb .sep{color:var(--line);font-size:10px}
.single{background:var(--card);border-radius:var(--radius-lg);box-shadow:var(--shadow);border:1px solid var(--line);overflow:hidden}
.post-hero{position:relative;aspect-ratio:16/8;overflow:hidden;background:var(--bg-soft)}
.post-hero img{width:100%;height:100%;object-fit:cover}
.post-hero .ph-lbl{position:absolute;top:18px;left:18px;background:var(--grad);color:#fff;font-size:12px;font-weight:700;padding:7px 16px;border-radius:50px;text-transform:uppercase;letter-spacing:.5px;box-shadow:var(--glow)}
.single-inner{padding:36px}
.post-h1{font-size:34px;line-height:1.22;margin-bottom:18px}
.post-meta{display:flex;flex-wrap:wrap;align-items:center;gap:22px;color:var(--muted);font-size:14px;padding-bottom:22px;margin-bottom:28px;border-bottom:1px solid var(--line)}
.post-meta .pm-author{display:flex;align-items:center;gap:11px}
.post-meta .pm-author .av{width:44px;height:44px;border-radius:50%;background:var(--grad);color:#fff;display:flex;align-items:center;justify-content:center;font-size:18px;font-weight:700}
.post-meta .pm-author b{color:var(--text);font-size:14.5px;display:block;line-height:1.3}
.post-meta .pm-author span{font-size:12.5px}
.post-meta .pm-item i{color:var(--primary);margin-right:6px}

/* ---- TOC ---- */
.toc{background:var(--bg-soft);border:1px solid var(--line);border-left:4px solid var(--primary);border-radius:14px;padding:18px 22px;margin:0 0 28px}
.toc-head{display:flex;align-items:center;justify-content:space-between;cursor:pointer;font-family:var(--font-head);font-weight:700;font-size:15px;color:var(--text)}
.toc-head i.tg{transition:.3s}
.toc.collapsed .toc-list{display:none}
.toc.collapsed .toc-head i.tg{transform:rotate(-90deg)}
.toc-list{margin-top:14px;counter-reset:toc}
.toc-list a{display:block;padding:7px 0 7px 30px;position:relative;color:var(--text-soft);font-size:14.5px;font-weight:500}
.toc-list a::before{counter-increment:toc;content:counter(toc);position:absolute;left:0;top:7px;width:21px;height:21px;border-radius:7px;background:var(--grad-soft);color:var(--primary);font-size:11px;font-weight:700;display:flex;align-items:center;justify-content:center}
.toc-list a:hover{color:var(--primary);padding-left:36px}
.toc-list a.active{color:#fff;background:var(--grad-soft);border-radius:10px;padding-left:36px;border:1px solid rgba(6,182,212,.25)}


/* ---- POST CONTENT ---- */
.post-content{font-size:17px;line-height:1.9;color:var(--text-soft)}
.post-content>*{margin-bottom:20px}
.post-content p{margin-bottom:20px}
.post-content h2,.post-content h3,.post-content h4{color:var(--text);margin:34px 0 14px;scroll-margin-top:90px}
.post-content h2{font-size:26px;padding-left:16px;border-left:5px solid var(--primary)}
.post-content h3{font-size:21px}
.post-content h4{font-size:18px}
.post-content a{color:var(--secondary);font-weight:600;border-bottom:1.5px solid transparent}
.post-content a:hover{color:var(--primary);border-bottom-color:var(--primary)}
.post-content img{border-radius:16px;margin:24px auto;box-shadow:var(--shadow)}
.post-content ul,.post-content ol{margin:0 0 22px 8px;padding-left:22px}
.post-content li{margin-bottom:10px;padding-left:4px}
.post-content ul li::marker{color:var(--primary)}
.post-content blockquote{border-left:4px solid var(--primary);background:var(--grad-soft);padding:18px 24px;margin:26px 0;border-radius:0 14px 14px 0;font-style:italic;color:var(--text);font-size:18px}
.post-content blockquote p:last-child{margin-bottom:0}
.post-content pre {
  position: relative;
  background: #090d16;
  color: #e2e8f0;
  padding: 44px 22px 22px 22px;
  border-radius: 16px;
  overflow: auto;
  margin: 24px 0;
  font-family: var(--font-mono);
  font-size: 13.5px;
  line-height: 1.65;
  border: 1px solid rgba(255,255,255,.06);
  box-shadow: 0 12px 32px rgba(0,0,0,0.22);
}
.post-content pre::before {
  content: '';
  position: absolute;
  top: 16px;
  left: 18px;
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: #ff5f56;
  box-shadow: 16px 0 0 #ffbd2e, 32px 0 0 #27c93f;
}
.post-content code {
  background: var(--bg-soft);
  color: var(--primary);
  padding: 3px 7px;
  border-radius: 6px;
  font-family: var(--font-mono);
  font-size: 13px;
  border: 1px solid var(--line);
}
.post-content pre code {
  background: none;
  color: inherit;
  padding: 0;
  border: 0;
}
.post-content table{width:100%;border-collapse:collapse;margin:24px 0;border-radius:12px;overflow:hidden;box-shadow:var(--shadow-sm)}
.post-content th,.post-content td{border:1px solid var(--line);padding:13px 16px;text-align:left}
.post-content th{background:var(--navy);color:#fff;font-family:var(--font-head)}
.post-content tr:nth-child(even){background:var(--bg-soft)}

/* ---- TAGS / SHARE / AUTHOR ---- */
.post-tags{display:flex;flex-wrap:wrap;gap:10px;align-items:center;margin:30px 0}
.post-tags .lab{font-weight:700;color:var(--text);font-size:14px;margin-right:4px}
.post-tags a{background:var(--bg-soft);color:var(--secondary);font-size:13px;font-weight:600;padding:7px 15px;border-radius:50px;border:1px solid var(--line);transition:.25s}
.post-tags a:hover{background:var(--grad);color:#fff;border-color:transparent}
.share-box{margin:30px 0;padding:24px;background:var(--bg-soft);border-radius:18px;border:1px solid var(--line)}
.share-box .sb-title{font-family:var(--font-head);font-weight:700;font-size:16px;margin-bottom:16px;color:var(--text)}
.share-row{display:flex;flex-wrap:wrap;gap:11px}
.share-row a{flex:1;min-width:130px;text-align:center;color:#fff;padding:13px;border-radius:12px;font-weight:600;font-size:14px;display:inline-flex;align-items:center;justify-content:center;gap:9px;transition:.25s}
.sh-wa{background:#25d366}.sh-fb{background:#1877f2}.sh-tw{background:#0f1419}.sh-tg{background:#229ed9}.sh-cp{background:var(--navy-2)}.sh-native{background:var(--grad);cursor:pointer}
.share-row a:hover{opacity:.92;color:#fff;transform:translateY(-3px)}
.author-box{display:flex;gap:20px;align-items:center;background:var(--grad-soft);border:1px solid var(--line);border-radius:20px;padding:24px;margin:32px 0}
.author-box .av{width:78px;height:78px;border-radius:50%;background:var(--grad);color:#fff;display:flex;align-items:center;justify-content:center;font-size:32px;font-weight:800;font-family:var(--font-head);flex-shrink:0;box-shadow:var(--glow)}
.author-box .ab-name{display:flex;align-items:center;gap:10px}
.author-box b{color:var(--text);font-size:18px;font-family:var(--font-head)}
.author-box .badge{background:var(--grad);color:#fff;font-size:10px;font-weight:700;padding:3px 9px;border-radius:50px;text-transform:uppercase}
.author-box p{color:var(--text-soft);font-size:14px;margin:7px 0 12px}
.author-box .ab-social a{width:34px;height:34px;border-radius:9px;background:var(--card);border:1px solid var(--line);color:var(--text);display:inline-flex;align-items:center;justify-content:center;margin-right:7px;font-size:14px}
.author-box .ab-social a:hover{background:var(--grad);color:#fff;border-color:transparent}

/* ---- POST NAV / RELATED ---- */
.related{margin-top:44px}
.related .post-grid{grid-template-columns:repeat(2,1fr);gap:20px}
@media(min-width:1200px){
  .related .post-grid{grid-template-columns:repeat(3,1fr)}
}
.post-nav{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-top:32px}
.post-nav a{background:var(--card);border:1px solid var(--line);border-radius:16px;padding:18px;transition:.25s;box-shadow:var(--shadow-sm)}
.post-nav a:hover{box-shadow:var(--shadow);transform:translateY(-3px)}
.post-nav small{color:var(--muted);font-size:12px;font-weight:600;text-transform:uppercase;letter-spacing:.5px}
.post-nav b{display:block;color:var(--text);font-size:15px;margin-top:6px;font-family:var(--font-head)}
.post-nav .nxt{text-align:right}

/* ---- COMMENTS ---- */
.comments-wrap{margin-top:32px;background:var(--card);border:1px solid var(--line);border-radius:20px;padding:28px;box-shadow:var(--shadow-sm)}

/* ----------------------------- 13. SIDEBAR ----------------------------- */
.sidebar{position:sticky;top:96px}
.sidebar .widget,.s-card{background:var(--card);border-radius:var(--radius);box-shadow:var(--shadow-sm);border:1px solid var(--line);padding:24px;margin-bottom:26px}
.sidebar h3,.sidebar .title,.s-title{font-family:var(--font-head);font-size:17px;margin-bottom:18px;padding-bottom:13px;position:relative;color:var(--text)}
.sidebar h3::after,.sidebar .title::after,.s-title::after{content:"";position:absolute;left:0;bottom:0;width:48px;height:3px;background:var(--grad);border-radius:3px}
.sidebar li{padding:11px 0;border-bottom:1px dashed var(--line)}
.sidebar li:last-child{border-bottom:0;padding-bottom:0}
.sidebar a{color:var(--text-soft);font-weight:500;font-size:14.5px}
.sidebar a:hover{color:var(--secondary)}
.about-card{text-align:center}
.about-card .ac-logo{width:72px;height:72px;margin:0 auto 14px;border-radius:18px;background:var(--navy-2);display:flex;align-items:center;justify-content:center;box-shadow:var(--glow);padding:8px}
.about-card p{font-size:14px;color:var(--text-soft);line-height:1.7;margin-bottom:14px}
.about-card .ac-social a{width:38px;height:38px;border-radius:11px;background:var(--bg-soft);border:1px solid var(--line);color:var(--text);display:inline-flex;align-items:center;justify-content:center;margin:0 4px;font-size:15px}
.about-card .ac-social a:hover{background:var(--grad);color:#fff;border-color:transparent;transform:translateY(-3px)}
/* popular posts */
.sidebar .PopularPosts ul{margin:0;display:flex;flex-direction:column;gap:16px}
.sidebar .PopularPosts li{padding:0;border-bottom:1px dashed var(--line);padding-bottom:16px;list-style:none}
.sidebar .PopularPosts li:last-child{border-bottom:0;padding-bottom:0}
.sidebar .PopularPosts .item-content{display:flex;align-items:center;gap:14px}
.sidebar .PopularPosts .item-thumbnail{float:none!important;margin:0!important;flex-shrink:0}
.sidebar .PopularPosts .item-thumbnail img{width:72px!important;height:72px!important;border-radius:13px;object-fit:cover}
.sidebar .PopularPosts .item-title{margin:0;line-height:1.45}
.sidebar .PopularPosts .item-title a{font-family:var(--font-head);font-size:14.5px;color:var(--text);font-weight:600;display:block}
.sidebar .PopularPosts .item-snippet{display:none}
/* labels as chips */
.sidebar .Label ul{display:flex;flex-wrap:wrap;gap:9px;margin:0}
.sidebar .Label li{border:0;padding:0}
.sidebar .Label a{background:var(--bg-soft);padding:8px 15px;border-radius:50px;font-size:13px;font-weight:600;color:var(--secondary);border:1px solid var(--line);display:inline-block}
.sidebar .Label a:hover{background:var(--grad);color:#fff;border-color:transparent}
/* newsletter */
.news-card{background:var(--navy);border:0;color:#fff;position:relative;overflow:hidden}
.news-card::before{content:"";position:absolute;top:-50%;right:-30%;width:80%;height:200%;background:radial-gradient(circle,rgba(6,182,212,.3),transparent 60%)}
.news-card .nc-in{position:relative;z-index:1}
.news-card .s-title{color:#fff}
.news-card p{color:#cbd5e1;font-size:13.5px;margin-bottom:14px}
.news-card .nc-form{display:flex;flex-direction:column;gap:10px}
.news-card input{padding:13px 16px;border-radius:12px;border:1px solid rgba(255,255,255,.16);background:rgba(255,255,255,.08);color:#fff;font-size:14px;outline:none}
.news-card input::placeholder{color:#94a3b8}
.news-card button{background:var(--grad);color:#fff;padding:13px;border-radius:12px;font-weight:700;font-size:14px}
.news-card button:hover{box-shadow:var(--glow)}

/* ----------------------------- 14. NEWSLETTER BAND --------------------- */
.cta-band{margin:20px 0 0;position:relative}
.cta-inner{background:var(--navy);border-radius:var(--radius-lg);padding:48px;text-align:center;position:relative;overflow:hidden;box-shadow:var(--shadow-lg)}
.cta-inner::before{content:"";position:absolute;inset:0;background:var(--grad);opacity:.12}
.cta-inner>*{position:relative;z-index:1}
.cta-inner h2{color:#fff;font-size:30px;margin-bottom:12px}
.cta-inner p{color:#cbd5e1;max-width:540px;margin:0 auto 26px}
.cta-form{display:flex;gap:12px;max-width:480px;margin:0 auto;flex-wrap:wrap}
.cta-form input{flex:1;min-width:200px;padding:15px 20px;border-radius:14px;border:1px solid rgba(255,255,255,.16);background:rgba(255,255,255,.1);color:#fff;font-size:15px;outline:none}
.cta-form input::placeholder{color:#94a3b8}
.cta-form button{background:var(--grad);color:#fff;padding:15px 30px;border-radius:14px;font-weight:700;box-shadow:var(--glow)}

/* ----------------------------- 15. FOOTER ------------------------------ */
.site-footer{background:var(--navy);color:#cbd5e1;margin-top:46px;position:relative;overflow:hidden}
.site-footer::before{content:"";position:absolute;top:0;left:0;right:0;height:3px;background:var(--grad)}
.footer-top{padding:56px 0 34px}
.footer-cols{display:grid;grid-template-columns:1.6fr 1fr 1fr 1.2fr;gap:36px}
.site-footer h4{color:#fff;font-size:16px;margin-bottom:18px;position:relative;padding-bottom:12px;font-family:var(--font-head)}
.site-footer h4::after{content:"";position:absolute;left:0;bottom:0;width:38px;height:3px;background:var(--grad);border-radius:3px}
.footer-about .brand{margin-bottom:16px}
.footer-about .brand .logo-text b{color:#fff}
.footer-about p{font-size:14px;line-height:1.8;margin-bottom:18px;color:#94a3b8}
.footer-social a{display:inline-flex;width:40px;height:40px;border-radius:11px;background:rgba(255,255,255,.07);align-items:center;justify-content:center;margin-right:9px;color:#fff;font-size:16px;transition:.25s}
.footer-social a:hover{background:var(--grad);transform:translateY(-3px)}
.site-footer a{color:#94a3b8}
.site-footer a:hover{color:var(--primary)}
.footer-links li{padding:7px 0;font-size:14px}
.footer-links li a{display:inline-flex;align-items:center;gap:9px}
.footer-links li a::before{content:"\f105";font-family:"Font Awesome 6 Free";font-weight:900;font-size:11px;color:var(--primary)}
.footer-contact li{display:flex;align-items:flex-start;gap:12px;padding:9px 0;font-size:13.5px;color:#94a3b8}
.footer-contact li i{width:34px;height:34px;border-radius:10px;background:rgba(255,255,255,.07);color:var(--primary);display:flex;align-items:center;justify-content:center;flex-shrink:0}
.footer-bottom{border-top:1px solid rgba(255,255,255,.08);padding:22px 0;font-size:13.5px}
.footer-bottom .wrap{display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:12px}
.footer-bottom .flag{display:inline-block;width:46px;height:3px;background:linear-gradient(to right,#ff9933 33%,#fff 33% 66%,#138808 66%);border-radius:2px;vertical-align:middle;margin:0 5px}
.footer-bottom .fb-links a{margin-left:18px}

/* ----------------------------- 16. FLOATING / BACK TOP ----------------- */
#toTop{position:fixed;right:24px;bottom:24px;width:52px;height:52px;border-radius:16px;background:var(--grad);color:#fff;font-size:18px;opacity:0;visibility:hidden;transition:.3s;z-index:900;box-shadow:var(--glow);display:flex;align-items:center;justify-content:center}
#toTop.show{opacity:1;visibility:visible}
#toTop:hover{transform:translateY(-4px)}
.float-share{position:fixed;left:18px;top:50%;transform:translateY(-50%);display:flex;flex-direction:column;gap:9px;z-index:800}
.float-share a{width:42px;height:42px;border-radius:12px;display:flex;align-items:center;justify-content:center;color:#fff;font-size:16px;box-shadow:var(--shadow);transition:.25s}
.float-share a:hover{transform:scale(1.12);color:#fff}

/* ----------------------------- 17. SEARCH OVERLAY ---------------------- */
.search-overlay{position:fixed;inset:0;background:rgba(7,15,28,.9);backdrop-filter:blur(8px);z-index:3100;display:flex;align-items:flex-start;justify-content:center;padding-top:14vh;opacity:0;visibility:hidden;transition:.3s}
.search-overlay.open{opacity:1;visibility:visible}
.search-box{width:90%;max-width:640px}
.search-box form{display:flex;background:var(--card);border-radius:16px;overflow:hidden;box-shadow:var(--shadow-lg);border:1px solid var(--line)}
.search-box input{flex:1;border:0;padding:20px 22px;font-size:17px;outline:none;background:var(--card);color:var(--text)}
.search-box button{background:var(--grad);color:#fff;padding:0 28px;font-size:18px}
.search-box .hint{color:#cbd5e1;font-size:13px;margin-top:14px;text-align:center}
.search-box .hint b{color:#fff}
.search-close{position:absolute;top:26px;right:32px;color:#fff;font-size:30px;width:48px;height:48px;border-radius:12px;background:rgba(255,255,255,.1)}
.search-close:hover{background:rgba(255,255,255,.2)}

/* ----------------------------- 18. MOBILE NAV -------------------------- */
.nav-backdrop{position:fixed;inset:0;background:rgba(7,15,28,.6);z-index:1400;opacity:0;visibility:hidden;transition:.3s;pointer-events:none}
.nav-backdrop.open{opacity:1;visibility:visible;pointer-events:auto}

/* ----------------------------- 19. 404 / STATUS ------------------------ */
.status-page{text-align:center;padding:70px 20px}
.status-page .big{font-family:var(--font-head);font-size:120px;font-weight:800;background:var(--grad);-webkit-background-clip:text;background-clip:text;-webkit-text-fill-color:transparent;line-height:1}
.status-page h2{font-size:28px;margin:10px 0 12px}
.status-page p{color:var(--muted);max-width:440px;margin:0 auto 26px}

/* ----------------------------- 20. ANIMATIONS -------------------------- */
.reveal{opacity:0;transform:translateY(30px);transition:.7s var(--ease)}
.reveal.in{opacity:1;transform:none}
@media (prefers-reduced-motion:reduce){*{animation:none!important;transition:none!important}.reveal{opacity:1;transform:none}}

/* ----------------------------- 21. WIDGET RESET ------------------------ */
.widget h2{display:none}
.main-section .widget{margin-bottom:30px}
.section-block{margin-bottom:42px}

/* ----------------------------- 22. RESPONSIVE -------------------------- */
@media(max-width:1100px){
  .hero h1{font-size:38px}
  .cat-grid{grid-template-columns:repeat(3,1fr)}
}
@media(max-width:980px){
  .layout-grid{grid-template-columns:1fr}
  .sidebar{position:static}
  .hero .wrap{grid-template-columns:1fr;gap:30px}
  .hero-visual{order:-1;display:none}
  .feat-grid{grid-template-columns:1fr}
  .feat-big{min-height:300px}
  .related .post-grid{grid-template-columns:repeat(2,1fr)}
  .float-share{display:none}
}
@media(max-width:860px){
  .ad-in-article[data-show-on-mobile='false']{display:none!important}
  .menu-toggle{display:flex}
  nav.main-nav{position:fixed;top:0;right:-100%;width:82%;max-width:340px;height:100vh;background:var(--card);padding:84px 18px 30px;transition:.35s var(--ease);box-shadow:-10px 0 40px rgba(0,0,0,.3);overflow-y:auto;z-index:1500;border-left:1px solid var(--line)}
  nav.main-nav.open{right:0}

  nav.main-nav>ul{flex-direction:column;align-items:stretch;gap:4px}
  nav.main-nav a{padding:15px 16px;border-radius:12px;background:var(--bg-soft);justify-content:space-between}
  nav.main-nav>ul>li>a::before{display:none}
  .submenu{position:static;opacity:1;visibility:visible;transform:none;box-shadow:none;border:0;border-top:0;background:transparent;padding:4px 0 4px 14px;max-height:0;overflow:hidden;transition:max-height .35s}
  nav.main-nav li.has-sub.open>.submenu{max-height:600px}
  nav.main-nav li.has-sub.open .sub-ic{transform:rotate(180deg)}
  .footer-cols{grid-template-columns:1fr 1fr}
  .cta-inner{padding:34px 22px}
  .cta-inner h2{font-size:24px}
}
@media(max-width:640px){
  .post-grid{grid-template-columns:1fr;gap:20px}
  .cat-grid{grid-template-columns:repeat(2,1fr);gap:10px}
  .related .post-grid{grid-template-columns:1fr}
  .post-nav{grid-template-columns:1fr}
  .single-inner{padding:22px}
  .post-h1{font-size:25px}
  .footer-cols{grid-template-columns:1fr}
  .tb-left span.hide-sm{display:none}
  .topbar .wrap{justify-content:center}
  .author-box{flex-direction:column;text-align:center}
  .post-content{font-size:16px;word-wrap:break-word;word-break:break-word}

  /* Homepage Hero Mobile Optimization */
  .hero{padding:48px 0;text-align:center}
  .hero h1{font-size:28px;margin-bottom:14px}
  .hero p{font-size:15px;margin:0 auto 24px}
  .hero-cta{justify-content:center;gap:10px}
  .hero-stats{justify-content:center;flex-wrap:wrap;gap:24px 16px;margin-top:28px}
  .hero-stats div b{font-size:22px}
  .hero-stats div span{font-size:11.5px}

  /* Homepage Category Strip Mobile Optimization */
  .cat-card{padding:16px 10px;border-radius:12px}
  .cat-ic{width:44px;height:44px;font-size:18px;margin:0 auto 10px;border-radius:12px}
  .cat-card b{font-size:14px}
  .cat-card small{font-size:11px}

  /* Homepage Featured Hero Posts Mobile Optimization */
  .feat-grid{margin-bottom:30px;gap:16px;grid-template-columns:1fr}
  .feat-side{gap:12px;display:flex;flex-direction:column}

  .feat-big{min-height:300px;border-radius:18px}
  .feat-big .feat-content{padding:20px}
  .feat-big h2{font-size:20px;line-height:1.45;margin-bottom:8px}
  .feat-big .feat-meta{margin-top:6px;font-size:11.5px}

  .feat-sm{
    position:relative;
    display:flex;
    flex-direction:row;
    align-items:center;
    background:var(--card);
    border:1px solid var(--line);
    border-radius:14px;
    padding:10px;
    min-height:0;
    gap:12px;
    box-shadow:var(--shadow-sm);
    overflow:hidden;
  }
  .feat-sm:hover{transform:translateY(-2px);box-shadow:var(--shadow)}
  .feat-sm .feat-overlay{display:none}
  .feat-sm img{
    position:static;
    width:84px;
    height:84px;
    border-radius:10px;
    object-fit:cover;
    flex-shrink:0;
    z-index:1;
  }
  .feat-sm .feat-content{
    position:static;
    padding:0;
    color:var(--text);
    display:flex;
    flex-direction:column;
    gap:4px;
    z-index:2;
  }
  .feat-sm .feat-content .lbl{
    font-size:9.5px;
    padding:3px 8px;
    margin-bottom:2px;
    align-self:flex-start;
  }
  .feat-sm h3{font-size:14.5px;line-height:1.45;margin-bottom:0}
  .feat-sm h3 a{color:var(--text)}
  .feat-sm h3 a:hover{color:var(--primary)}

  /* Homepage Newsletter Band Mobile Optimization */
  .cta-inner{padding:28px 16px}
  .cta-form{flex-direction:column;gap:10px;width:100%;max-width:320px}
  .cta-form input, .cta-form button{width:100%;min-width:0;text-align:center;padding:12px 20px}

  /* Prevent header overflow */
  .header-main .wrap{gap:10px;padding:0 12px}
  .brand{gap:8px}
  .brand .logo-mark{width:40px;height:40px;border-radius:12px;padding:4px}
  .brand .logo-text b{font-size:18px}
  .brand .logo-text span{font-size:9.5px;letter-spacing:1.5px}
  .nav-tools{gap:6px}
  .icon-btn{width:38px;height:38px;border-radius:10px;font-size:14px}

  /* Blog Post Cards Mobile Optimization */
  .p-card{border-radius:14px}
  .p-body{padding:16px}
  .p-title{font-size:16px;margin-bottom:6px;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;text-overflow:ellipsis;line-height:1.5}
  .p-snippet{font-size:13.5px;margin-bottom:12px;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;text-overflow:ellipsis;line-height:1.55}
  .p-foot{padding-top:10px}
  .p-author b{font-size:12px}
  .p-author span{font-size:11px}
}
@media(min-width:861px){.menu-toggle{display:none!important}}

/* ----------------------------- 23. ADSENSE ZONES ----------------------- */
.ad-zone{margin:26px 0;text-align:center;min-height:90px;display:flex;flex-direction:column;align-items:center;justify-content:center;background:var(--bg-soft);border:1px dashed var(--line);border-radius:14px;padding:14px;overflow:hidden}
.ad-zone .ad-lbl{font-size:10px;letter-spacing:2px;text-transform:uppercase;color:var(--muted);margin-bottom:6px;font-weight:600}
.ad-zone ins{display:block;width:100%}
.ad-in-article{margin:30px 0}
.sidebar .ad-zone{margin:0}

/* ----------------------------- 24. FAQ ACCORDION ----------------------- */
.faq-block{margin:30px 0}
.faq-block .faq-h{font-family:var(--font-head);font-size:23px;margin-bottom:16px;display:flex;align-items:center;gap:10px;color:var(--text)}
.faq-block .faq-h i{color:var(--primary)}
.faq-q{display:flex;align-items:center;justify-content:space-between;gap:14px;cursor:pointer;background:var(--card);border:1px solid var(--line);border-radius:14px;padding:16px 20px;margin-bottom:12px;font-family:var(--font-head);font-weight:600;font-size:16px;color:var(--text);transition:.25s;list-style:none}
.faq-q::-webkit-details-marker{display:none}
.faq-q .fq-ic{width:28px;height:28px;border-radius:9px;background:var(--grad-soft);color:var(--primary);display:flex;align-items:center;justify-content:center;flex-shrink:0;transition:.3s}
details[open] .faq-q{border-color:var(--primary);border-bottom-left-radius:0;border-bottom-right-radius:0;margin-bottom:0}
details[open] .faq-q .fq-ic{transform:rotate(45deg);background:var(--grad);color:#fff}
.faq-a{background:var(--card);border:1px solid var(--line);border-top:0;border-radius:0 0 14px 14px;padding:4px 20px 18px;margin-bottom:12px;color:var(--text-soft);font-size:15px;line-height:1.8}

/* ----------------------------- 25. WEB STORIES STRIP ------------------- */
.stories-strip{padding:30px 0 4px}
.stories-row{display:flex;gap:16px;overflow-x:auto;padding:6px 2px 16px;scroll-snap-type:x mandatory;scrollbar-width:none}
.stories-row::-webkit-scrollbar{display:none}
.story-card{flex:0 0 150px;height:240px;border-radius:20px;overflow:hidden;position:relative;scroll-snap-align:start;box-shadow:var(--shadow);border:3px solid transparent;background:var(--navy);transition:.3s}
.story-card:hover{transform:translateY(-6px);border-color:var(--primary)}
.story-card img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover}
.story-card .st-ov{position:absolute;inset:0;background:linear-gradient(to top,rgba(7,15,28,.9),transparent 60%);z-index:1}
.story-card .st-t{position:absolute;left:0;right:0;bottom:0;z-index:2;padding:14px;color:#fff;font-size:13px;font-weight:600;line-height:1.35}
.story-card .st-ring{position:absolute;top:10px;left:10px;z-index:2;width:30px;height:30px;border-radius:50%;background:var(--grad);display:flex;align-items:center;justify-content:center;color:#fff;font-size:12px}

/* ----------------------------- 26. RELATED POSTS ----------------------- */
#relatedWrap{margin-top:44px}
.rel-loading{text-align:center;color:var(--muted);padding:20px;font-size:14px}

/* ----------------------------- 27. COOKIE CONSENT ---------------------- */
#cookieBar{position:fixed;left:18px;right:18px;bottom:18px;max-width:560px;margin:0 auto;background:var(--card);border:1px solid var(--line);border-radius:18px;box-shadow:var(--shadow-lg);padding:20px 22px;z-index:3000;display:flex;align-items:center;gap:16px;flex-wrap:wrap;transform:translateY(160%);transition:transform .5s var(--ease)}
#cookieBar.show{transform:translateY(0)}
#cookieBar .ck-ic{width:44px;height:44px;border-radius:12px;background:var(--grad);color:#fff;display:flex;align-items:center;justify-content:center;font-size:20px;flex-shrink:0}
#cookieBar p{flex:1;min-width:200px;font-size:13.5px;color:var(--text-soft);margin:0}
#cookieBar p a{font-weight:600}
#cookieBar .ck-btns{display:flex;gap:9px}
#cookieBar button{padding:10px 20px;border-radius:11px;font-weight:700;font-size:13.5px}
#cookieBar .ck-ok{background:var(--grad);color:#fff;box-shadow:var(--glow)}
#cookieBar .ck-no{background:var(--bg-soft);color:var(--text);border:1px solid var(--line)}
@media(max-width:520px){#cookieBar{flex-direction:column;text-align:center}#cookieBar .ck-btns{width:100%}#cookieBar button{flex:1}}

/* ----------------------------- 28. PREMIUM DEVELOPER UI FEATURES ---------------------- */
/* Card Neon Glow Hover */
.p-card:hover {
  transform: translateY(-7px);
  box-shadow: 0 10px 30px rgba(6, 182, 212, 0.15), var(--shadow-lg);
  border-color: var(--primary) !important;
}
html[data-theme='dark'] .p-card:hover {
  box-shadow: 0 10px 40px rgba(6, 182, 212, 0.25), var(--shadow-lg);
}

/* Copy Code Button */
.post-content pre {
  position: relative;
}
.copy-code-btn {
  position: absolute;
  top: 10px;
  right: 10px;
  background: rgba(255, 255, 255, 0.08);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  border: 1px solid rgba(255, 255, 255, 0.16);
  color: #cbd5e1;
  border-radius: 8px;
  padding: 6px 12px;
  font-size: 12px;
  font-weight: 600;
  transition: all 0.25s var(--ease);
  z-index: 10;
  display: inline-flex;
  align-items: center;
  gap: 6px;
}
.copy-code-btn:hover {
  background: var(--grad);
  color: #fff;
  border-color: transparent;
  transform: translateY(-1px);
  box-shadow: var(--glow);
}
.copy-code-btn i {
  font-size: 13px;
}

/* Prism.js Syntax Highlighter CSS Overrides */
.post-content pre[class*="language-"] {
  background: #090d16 !important;
  padding: 44px 22px 22px 22px !important;
  border-radius: 16px !important;
  border: 1px solid rgba(255,255,255,.06) !important;
  box-shadow: 0 12px 32px rgba(0,0,0,0.22) !important;
  margin: 24px 0 !important;
}
.post-content code[class*="language-"], .post-content pre[class*="language-"] {
  font-family: var(--font-mono) !important;
  font-size: 13.5px !important;
  line-height: 1.65 !important;
  text-shadow: none !important;
}
/* Prism Tomorrow/Dracula token colors override for neon look */
.token.comment, .token.prolog, .token.doctype, .token.cdata { color: #6272a4 !important; font-style: italic; }
.token.punctuation { color: #f8f8f2 !important; }
.token.property, .token.tag, .token.constant, .token.symbol, .token.deleted { color: #ff79c6 !important; }
.token.boolean, .token.number { color: #bd93f9 !important; }
.token.selector, .token.attr-name, .token.string, .token.char, .token.builtin, .token.inserted { color: #50fa7b !important; }
.token.operator, .token.entity, .token.url, .language-css .token.string, .style .token.string { color: #f8f8f2 !important; }
.token.atrule, .token.attr-value, .token.keyword { color: #ff79c6 !important; font-weight: bold; }
.token.function, .token.class-name { color: #8be9fd !important; }
.token.regex, .token.important, .token.variable { color: #f1fa8c !important; }

/* Search Suggestions Autocomplete Dropdown */
.search-box {
  position: relative;
}
.search-suggestions {
  position: absolute;
  left: 0;
  right: 0;
  top: calc(100% + 12px);
  background: var(--card);
  border: 1px solid var(--line);
  border-radius: 16px;
  box-shadow: var(--shadow-lg);
  max-height: 380px;
  overflow-y: auto;
  z-index: 3200;
  padding: 10px;
  text-align: left;
}
.suggestion-item {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 10px;
  border-radius: 10px;
  transition: background .2s var(--ease);
  color: var(--text);
  font-weight: 500;
  font-size: 14px;
  border-bottom: 1px dashed var(--line-2);
  text-decoration: none;
}
.suggestion-item:last-child {
  border-bottom: none;
}
.suggestion-item:hover {
  background: var(--grad-soft);
  color: var(--primary);
}
.suggestion-item img {
  width: 48px;
  height: 48px;
  border-radius: 8px;
  object-fit: cover;
  flex-shrink: 0;
}
.suggestion-item .s-info {
  display: flex;
  flex-direction: column;
  gap: 4px;
  overflow: hidden;
}
.suggestion-item .s-title {
  font-family: var(--font-head);
  font-weight: 600;
  font-size: 14px;
  line-height: 1.35;
  color: var(--text);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.suggestion-item:hover .s-title {
  color: var(--primary);
}
.suggestion-item .s-meta {
  font-size: 11px;
  color: var(--muted);
}
/* Category Active Filter State */
.cat-card.active {
  transform: translateY(-8px);
  box-shadow: var(--shadow-lg);
  border-color: transparent !important;
}
.cat-card.active::before {
  opacity: 1;
}
.cat-card.active .cat-ic, .cat-card.active b, .cat-card.active small {
  color: #fff;
}
.cat-card.active .cat-ic {
  background: rgba(255, 255, 255, 0.2);
}

/* GitHub Live Stats Widget */
.github-stats {
  margin-top: 15px;
  background: var(--grad-soft);
  border: 1px solid rgba(6, 182, 212, 0.15);
  border-radius: var(--radius-sm);
  padding: 10px 14px;
  display: none; /* Flex when loaded via JS */
  align-items: center;
  justify-content: center;
  gap: 8px;
  transition: all 0.3s var(--ease);
}
.github-stats:hover {
  transform: translateY(-2px);
  border-color: var(--primary);
  box-shadow: 0 4px 15px rgba(6, 182, 212, 0.15);
}
.github-stats a {
  display: flex;
  align-items: center;
  gap: 8px;
  color: var(--text-soft);
  text-decoration: none;
  font-size: 13.5px;
  font-weight: 500;
  width: 100%;
  justify-content: center;
}
.github-stats i {
  font-size: 16px;
  color: var(--primary);
}
.github-stats span {
  font-weight: 700;
  color: var(--primary);
}

/* Quote Widget Styling */
.quote-card {
  position: relative;
  background: var(--card);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 24px;
  margin-bottom: 30px;
  overflow: hidden;
  transition: all 0.3s var(--ease);
}
.quote-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow);
  border-color: rgba(6, 182, 212, 0.2);
}
.quote-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  width: 4px;
  height: 100%;
  background: var(--grad);
}
.quote-card .s-title {
  margin-bottom: 12px;
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 16px;
}
.quote-body {
  font-size: 14.5px;
  line-height: 1.6;
  color: var(--text-soft);
  font-style: italic;
  margin-bottom: 8px;
  position: relative;
}
.quote-author {
  font-size: 12px;
  font-weight: 600;
  color: var(--primary);
  text-align: right;
  font-family: var(--font-head);
}

/* --- Dynamic Ticker Header Animation --- */
#topbarTicker {
  display: inline-block;
  transition: opacity 0.4s var(--ease), transform 0.4s var(--ease);
}
#topbarTicker.fade-out {
  opacity: 0;
  transform: translateY(-8px);
}
#topbarTicker.fade-in {
  opacity: 1;
  transform: translateY(0);
}
#tickerIcon {
  transition: transform 0.5s var(--ease);
}
#tickerIcon.spin {
  transform: rotate(360deg);
}

/* --- QR Share Zone (Article Pages) --- */
.qr-share-zone {
  margin-top: 20px;
  padding-top: 18px;
  border-top: 1px dashed var(--line);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 15px;
}
.qr-card-info b {
  font-size: 14px;
  color: var(--text);
  display: block;
  margin-bottom: 4px;
}
.qr-card-info p {
  font-size: 12.5px;
  color: var(--text-soft);
}
.qr-wrapper {
  background: #fff;
  padding: 6px;
  border-radius: var(--radius-sm);
  border: 1px solid var(--line);
  box-shadow: var(--shadow-sm);
  transition: all 0.3s var(--ease);
}
.qr-wrapper:hover {
  transform: scale(1.08);
  box-shadow: var(--shadow);
}
.qr-wrapper img {
  width: 78px;
  height: 78px;
  display: block;
}

/* --- Coder Humor Widget --- */
.joke-card {
  position: relative;
  background: var(--card);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 24px;
  margin-bottom: 30px;
  overflow: hidden;
  transition: all 0.3s var(--ease);
}
.joke-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow);
  border-color: rgba(6, 182, 212, 0.2);
}
.joke-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  width: 4px;
  height: 100%;
  background: linear-gradient(to bottom, #8b5cf6, #2563eb);
}
.joke-card .s-title {
  margin-bottom: 12px;
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 16px;
}
.joke-body {
  font-size: 14px;
  line-height: 1.6;
  color: var(--text-soft);
  margin-bottom: 16px;
  min-height: 48px;
}
.joke-refresh-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 12.5px;
  font-weight: 600;
  color: var(--primary);
  background: var(--grad-soft);
  padding: 8px 16px;
  border-radius: 50px;
  transition: all 0.2s var(--ease);
  border: 1px solid rgba(6, 182, 212, 0.15);
}
.joke-refresh-btn:hover {
  background: var(--primary);
  color: #fff;
  transform: translateY(-1px);
  box-shadow: 0 4px 10px rgba(6, 182, 212, 0.2);
}
.joke-refresh-btn i {
  font-size: 12px;
  transition: transform 0.5s var(--ease);
}
.joke-refresh-btn:hover i {
  transform: rotate(180deg);
}

/* --- Luxury Text-to-Speech Player --- */
.tts-player {
  background: var(--bg-soft);
  border: 1px solid var(--line);
  border-radius: var(--radius-sm);
  padding: 16px 20px;
  margin-bottom: 24px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 15px;
  flex-wrap: wrap;
  position: relative;
  overflow: hidden;
  transition: all 0.3s var(--ease);
}
.tts-player:hover {
  border-color: rgba(6, 182, 212, 0.25);
  box-shadow: var(--shadow-sm);
}
.tts-player::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  width: 3px;
  height: 100%;
  background: var(--grad);
}
.tts-meta {
  display: flex;
  align-items: center;
  gap: 10px;
}
.tts-meta i {
  font-size: 18px;
  color: var(--primary);
}
.tts-pulse.active {
  animation: pulse-audio 1.5s infinite var(--ease);
}
@keyframes pulse-audio {
  0%, 100% { transform: scale(1); opacity: 1; }
  50% { transform: scale(1.15); opacity: 0.7; }
}
.tts-status-text {
  font-size: 13.5px;
  font-weight: 600;
  color: var(--text-soft);
}
.tts-controls {
  display: flex;
  align-items: center;
  gap: 8px;
}
.tts-btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 13px;
  font-weight: 700;
  padding: 8px 16px;
  border-radius: 50px;
  cursor: pointer;
  transition: all 0.28s var(--ease);
  border: 1px solid transparent;
}
.tts-play-btn {
  background: var(--grad);
  color: #fff;
  box-shadow: 0 4px 12px rgba(6, 182, 212, 0.25);
}
.tts-play-btn:hover {
  transform: translateY(-1.5px);
  box-shadow: 0 6px 18px rgba(6, 182, 212, 0.35);
  color: #fff;
}
.tts-stop-btn {
  background: var(--bg);
  border-color: var(--line);
  color: var(--text-soft);
}
.tts-stop-btn:hover {
  background: #ef4444;
  color: #fff;
  border-color: transparent;
  transform: translateY(-1.5px);
}
.tts-speed-selector {
  position: relative;
}
.tts-speed-btn {
  background: var(--bg);
  border: 1px solid var(--line);
  color: var(--text-soft);
  font-size: 12px;
  font-weight: 700;
  padding: 7px 12px;
  border-radius: 50px;
  cursor: pointer;
  transition: all 0.2s var(--ease);
}
.tts-speed-btn:hover {
  border-color: var(--primary);
  color: var(--primary);
}
.tts-speed-dropdown {
  position: absolute;
  bottom: calc(100% + 8px);
  right: 0;
  background: var(--card);
  border: 1px solid var(--line);
  border-radius: 10px;
  padding: 6px;
  box-shadow: var(--shadow);
  display: none;
  flex-direction: column;
  min-width: 70px;
  z-index: 10;
}
.tts-speed-dropdown.open {
  display: flex;
}
.tts-speed-dropdown span {
  font-size: 12px;
  font-weight: 600;
  padding: 6px 10px;
  border-radius: 6px;
  cursor: pointer;
  color: var(--text-soft);
  text-align: center;
  transition: all 0.2s;
}
.tts-speed-dropdown span:hover, .tts-speed-dropdown span.active {
  background: var(--grad-soft);
  color: var(--primary);
}
.tts-progress-bar-container {
  position: absolute;
  bottom: 0;
  left: 0;
  width: 100%;
  height: 3px;
  background: var(--line);
}
.tts-progress-bar {
  height: 100%;
  width: 0;
  background: var(--grad);
  transition: width 0.1s linear;
}
@media (max-width: 640px) {
  .tts-player {
    flex-direction: column;
    align-items: stretch;
  }
  .tts-controls {
    justify-content: flex-start;
  }
}

    /* GitHub Projects & Tech News Widgets */
    .github-projects-widget, .tech-news-widget {
      background: var(--card-bg);
      border: 1px solid var(--border);
      border-radius: var(--radius-lg);
      padding: 20px;
      box-shadow: var(--shadow-sm);
      transition: transform var(--trans), box-shadow var(--trans);
      margin-bottom: 20px;
    }
    .github-projects-widget:hover, .tech-news-widget:hover {
      transform: translateY(-2px);
      box-shadow: var(--shadow-md);
    }
    .sec-head-small {
      border-bottom: 1px solid var(--border);
      padding-bottom: 10px;
      margin-bottom: 15px;
    }
    .sec-head-small .s-title {
      font-size: 15px;
      color: var(--text-heading);
      display: flex;
      align-items: center;
      gap: 8px;
      margin: 0;
      font-family: var(--font-head);
    }
    .gh-loading, .news-loading {
      text-align: center;
      padding: 20px 0;
      color: var(--text-muted);
      font-size: 13px;
    }
    .gh-projects-list, .news-list {
      display: flex;
      flex-direction: column;
      gap: 12px;
    }
    .gh-repo-card {
      background: rgba(255, 255, 255, 0.02);
      border: 1px solid var(--border);
      border-radius: var(--radius-md);
      padding: 12px;
      transition: border-color var(--trans);
    }
    .gh-repo-card:hover {
      border-color: var(--accent);
    }
    .gh-repo-title {
      font-size: 13.5px;
      font-weight: 600;
      color: var(--text-heading);
      margin-bottom: 6px;
      display: flex;
      align-items: center;
      justify-content: space-between;
    }
    .gh-repo-title a {
      color: inherit;
      transition: color var(--trans);
      text-decoration: none;
    }
    .gh-repo-title a:hover {
      color: var(--accent);
    }
    .gh-repo-desc {
      font-size: 12px;
      color: var(--text-muted);
      line-height: 1.5;
      margin-bottom: 8px;
    }
    .gh-repo-meta {
      display: flex;
      align-items: center;
      gap: 12px;
      font-size: 11px;
      color: var(--text-muted);
    }
    .gh-lang-dot {
      display: inline-block;
      width: 8px;
      height: 8px;
      border-radius: 50%;
      background: var(--accent);
      margin-right: 4px;
    }

    /* News List Styles */
    .news-item {
      display: flex;
      align-items: flex-start;
      gap: 10px;
      padding-bottom: 10px;
      border-bottom: 1px dashed var(--border);
    }
    .news-item:last-child {
      border-bottom: 0;
      padding-bottom: 0;
    }
    .news-num {
      font-size: 14px;
      font-weight: 700;
      color: var(--accent);
      min-width: 20px;
    }
    .news-details {
      flex: 1;
    }
    .news-title {
      font-size: 12.5px;
      font-weight: 500;
      color: var(--text-heading);
      line-height: 1.4;
      margin-bottom: 4px;
      margin-top: 0;
    }
    .news-title a {
      color: inherit;
      transition: color var(--trans);
      text-decoration: none;
    }
    .news-title a:hover {
      color: var(--accent);
    }
    .news-meta {
      font-size: 10.5px;
      color: var(--text-muted);
    }


    /* Command Center Glassmorphism Overlay */
    .cmd-overlay {
      position: fixed;
      inset: 0;
      background: rgba(2, 6, 17, 0.7);
      backdrop-filter: blur(12px);
      -webkit-backdrop-filter: blur(12px);
      z-index: 9999;
      display: flex;
      justify-content: center;
      align-items: flex-start;
      padding-top: 12vh;
      opacity: 0;
      pointer-events: none;
      transition: opacity 0.2s ease;
    }
    .cmd-overlay.open {
      opacity: 1;
      pointer-events: auto;
    }
    .cmd-box {
      width: 90%;
      max-width: 600px;
      background: rgba(15, 23, 42, 0.95);
      border: 1px solid rgba(6, 182, 212, 0.25);
      border-radius: 16px;
      box-shadow: 0 20px 50px rgba(0, 0, 0, 0.5), 0 0 20px rgba(6, 182, 212, 0.1);
      overflow: hidden;
      transform: translateY(-20px);
      transition: transform 0.25s cubic-bezier(0.16, 1, 0.3, 1);
      display: flex;
      flex-direction: column;
    }
    .cmd-overlay.open .cmd-box {
      transform: translateY(0);
    }
    .cmd-header {
      display: flex;
      align-items: center;
      padding: 16px 20px;
      border-bottom: 1px solid rgba(255, 255, 255, 0.08);
      gap: 12px;
    }
    .cmd-icon {
      color: #06b6d4;
      font-size: 18px;
    }
    .cmd-input {
      flex: 1;
      background: none;
      border: 0;
      outline: none;
      color: #f8fafc;
      font-size: 16px;
      font-family: inherit;
    }
    .cmd-input::placeholder {
      color: #64748b;
    }
    .cmd-close-btn {
      background: rgba(255, 255, 255, 0.05);
      border: 0;
      color: #94a3b8;
      font-size: 11px;
      padding: 4px 8px;
      border-radius: 6px;
      cursor: pointer;
      transition: background 0.2s;
    }
    .cmd-close-btn:hover {
      background: rgba(255, 255, 255, 0.1);
      color: #fff;
    }
    .cmd-content {
      max-height: 380px;
      overflow-y: auto;
      padding: 10px;
      display: flex;
      flex-direction: column;
      gap: 4px;
    }
    .cmd-group-title {
      font-size: 11px;
      text-transform: uppercase;
      letter-spacing: 1px;
      color: #64748b;
      padding: 8px 10px 4px;
      font-weight: 700;
    }
    .cmd-item {
      display: flex;
      align-items: center;
      padding: 10px 14px;
      border-radius: 10px;
      cursor: pointer;
      transition: all 0.15s ease;
      gap: 12px;
      color: #cbd5e1;
      text-decoration: none;
    }
    .cmd-item-icon {
      font-size: 14px;
      color: #94a3b8;
      width: 20px;
      text-align: center;
    }
    .cmd-item-text {
      flex: 1;
      font-size: 13.5px;
      font-weight: 500;
    }
    .cmd-item-badge {
      font-size: 10px;
      background: rgba(255, 255, 255, 0.05);
      color: #94a3b8;
      padding: 2px 6px;
      border-radius: 4px;
      font-family: var(--font-mono);
    }
    .cmd-item.active {
      background: rgba(6, 182, 212, 0.15);
      color: #fff;
    }
    .cmd-item.active .cmd-item-icon {
      color: #06b6d4;
    }
    .cmd-item.active .cmd-item-badge {
      background: rgba(6, 182, 212, 0.2);
      color: #06b6d4;
    }
    .cmd-footer {
      background: rgba(2, 6, 17, 0.4);
      padding: 12px 20px;
      border-top: 1px solid rgba(255, 255, 255, 0.05);
      display: flex;
      justify-content: space-between;
      align-items: center;
      font-size: 11px;
      color: #64748b;
    }
    .cmd-shortcuts {
      display: flex;
      gap: 12px;
    }
    .cmd-shortcuts span {
      display: flex;
      align-items: center;
      gap: 4px;
    }
    .cmd-key {
      display: inline-block;
      background: rgba(255, 255, 255, 0.06);
      border: 1px solid rgba(255, 255, 255, 0.1);
      box-shadow: 0 1px 0 rgba(0,0,0,0.4);
      padding: 1px 5px;
      border-radius: 4px;
      font-size: 9px;
      font-family: var(--font-mono);
      color: #cbd5e1;
    }

    /* 3D Isometric Floating Trigger Button */
    .cmd-trigger-btn {
      position: fixed;
      bottom: 24px;
      right: 84px;
      width: 48px;
      height: 48px;
      border-radius: 12px;
      background: #020617;
      border: 1px solid #06b6d4;
      color: #06b6d4;
      font-size: 18px;
      display: flex;
      justify-content: center;
      align-items: center;
      cursor: pointer;
      z-index: 999;
      transform: perspective(600px) rotateX(15deg) rotateY(-15deg) rotateZ(0deg);
      box-shadow: 4px 4px 0px 0px #06b6d4, 8px 8px 16px rgba(0, 0, 0, 0.4);
      transition: transform 0.2s, box-shadow 0.2s, background 0.2s, color 0.2s;
    }
    .cmd-trigger-btn:hover {
      background: #06b6d4;
      color: #020617;
      transform: perspective(600px) rotateX(10deg) rotateY(-10deg) rotateZ(5deg) translate3d(-2px, -2px, 10px);
      box-shadow: 6px 6px 0px 0px #2563eb, 12px 12px 24px rgba(6, 182, 212, 0.3);
    }
    .cmd-trigger-btn:active {
      transform: perspective(600px) rotateX(15deg) rotateY(-15deg) rotateZ(0deg) translate3d(2px, 2px, -2px);
      box-shadow: 2px 2px 0px 0px #06b6d4, 4px 4px 8px rgba(0, 0, 0, 0.4);
    }
    @media (max-width: 640px) {
      .cmd-trigger-btn {
        bottom: 20px;
        right: 76px;
        width: 44px;
        height: 44px;
        font-size: 16px;
      }
      .cmd-box {
        width: 95%;
      }
    }


    /* 3D Parallax Layout Setup */
    body {
      perspective: 1200px;
    }
    .p-card, .s-card, .gh-repo-card {
      transform-style: preserve-3d;
      backface-visibility: hidden;
      transition: transform 0.15s ease-out, box-shadow 0.15s ease-out;
    }
    .p-card *, .s-card *, .gh-repo-card * {
      /* Create micro-depth for child items */
      transform-style: preserve-3d;
    }

    /* comments link hover */
    .pm-comments-link {
      color: var(--primary) !important;
      font-weight: 600;
      transition: opacity 0.2s;
    }
    .pm-comments-link:hover {
      opacity: 0.8;
      text-decoration: underline;
    }

    /* Helpful post feedback widget */
    .post-feedback {
      background: var(--card);
      border: 1px solid var(--line);
      border-radius: var(--radius);
      padding: 24px;
      margin: 28px 0;
      text-align: center;
      transition: all 0.3s var(--ease);
      box-shadow: var(--shadow-sm);
    }
    .post-feedback h4 {
      font-size: 17px;
      margin-bottom: 16px;
      color: var(--text);
    }
    .fb-options {
      display: flex;
      justify-content: center;
      gap: 16px;
      flex-wrap: wrap;
    }
    .fb-btn {
      padding: 11px 22px;
      border-radius: var(--radius-sm);
      font-size: 14.5px;
      font-weight: 600;
      display: inline-flex;
      align-items: center;
      gap: 8px;
      background: var(--bg-soft);
      color: var(--text-soft);
      border: 1px solid var(--line);
      transition: all 0.2s var(--ease);
    }
    .fb-btn:hover {
      background: var(--card);
      transform: translateY(-2px);
      box-shadow: var(--shadow-sm);
    }
    .fb-yes:hover {
      border-color: #22c55e;
      color: #22c55e;
    }
    .fb-no:hover {
      border-color: #ef4444;
      color: #ef4444;
    }
    .fb-thanks-inner {
      display: flex;
      align-items: center;
      justify-content: center;
      gap: 16px;
      text-align: left;
      animation: scaleIn 0.3s var(--ease);
    }
    .fb-check-icon {
      font-size: 32px;
      color: #22c55e;
      animation: pulseCheck 1.2s infinite;
    }
    .fb-thanks b {
      font-size: 16px;
      color: var(--text);
      display: block;
      margin-bottom: 2px;
    }
    .fb-thanks p {
      font-size: 13.5px;
      color: var(--muted);
    }

    /* Medium-Style Highlight Tooltip */
    .share-tooltip {
      position: absolute;
      background: #0f1d30;
      border: 1px solid #1f3550;
      box-shadow: 0 8px 30px rgba(0,0,0,0.5);
      border-radius: 10px;
      padding: 6px;
      display: flex;
      gap: 4px;
      z-index: 2500;
      pointer-events: auto;
      transform: translateY(-10px);
      opacity: 0;
      transition: opacity 0.2s, transform 0.2s;
    }
    .share-tooltip.show {
      opacity: 1;
      transform: translateY(0);
    }
    .share-tooltip::after {
      content: "";
      position: absolute;
      bottom: -6px;
      left: 50%;
      transform: translateX(-50%);
      border-width: 6px 6px 0;
      border-style: solid;
      border-color: #0f1d30 transparent transparent;
      display: block;
      width: 0;
    }
    .share-tooltip-btn {
      background: none;
      border: none;
      color: #b8c4d8;
      padding: 6px 12px;
      font-size: 13px;
      font-weight: 600;
      cursor: pointer;
      display: inline-flex;
      align-items: center;
      gap: 6px;
      border-radius: 6px;
      transition: background 0.2s, color 0.2s;
    }
    .share-tooltip-btn:hover {
      background: rgba(255,255,255,0.08);
      color: #fff;
    }

    /* Quiz Widget Styles */
    .tech-quiz-widget {
      position: relative;
    }
    .quiz-body {
      display: flex;
      flex-direction: column;
      gap: 16px;
      margin-top: 14px;
    }
    .quiz-q {
      font-size: 14.5px;
      font-weight: 600;
      line-height: 1.5;
      color: var(--text);
    }
    .quiz-opts {
      display: flex;
      flex-direction: column;
      gap: 10px;
    }
    .quiz-opt {
      width: 100%;
      text-align: left;
      padding: 12px 16px;
      background: var(--bg-soft);
      border: 1px solid var(--line);
      border-radius: var(--radius-sm);
      font-size: 13.5px;
      color: var(--text-soft);
      font-weight: 500;
      transition: all 0.2s var(--ease);
      display: flex;
      align-items: center;
      gap: 10px;
    }
    .quiz-opt:hover:not(:disabled) {
      background: var(--card);
      border-color: var(--primary);
      color: var(--primary);
      transform: translateX(4px);
      box-shadow: var(--shadow-sm);
    }
    .quiz-opt.correct {
      background: rgba(34, 197, 94, 0.12) !important;
      border-color: #22c55e !important;
      color: #22c55e !important;
      font-weight: 600;
    }
    .quiz-opt.incorrect {
      background: rgba(239, 68, 68, 0.12) !important;
      border-color: #ef4444 !important;
      color: #ef4444 !important;
      font-weight: 600;
    }
    .quiz-opt-dot {
      display: inline-block;
      width: 16px;
      height: 16px;
      border-radius: 50%;
      border: 2px solid var(--muted);
      flex-shrink: 0;
      transition: all 0.2s var(--ease);
      position: relative;
    }
    .quiz-opt:hover:not(:disabled) .quiz-opt-dot {
      border-color: var(--primary);
    }
    .quiz-opt.correct .quiz-opt-dot {
      border-color: #22c55e;
      background: #22c55e;
    }
    .quiz-opt.incorrect .quiz-opt-dot {
      border-color: #ef4444;
      background: #ef4444;
    }
    .quiz-expl {
      padding: 12px 14px;
      border-radius: var(--radius-sm);
      background: var(--bg-soft);
      border-left: 4px solid var(--primary);
      font-size: 13px;
      color: var(--text-soft);
      line-height: 1.5;
      animation: slideDown 0.3s var(--ease);
    }
    .quiz-next-btn {
      width: 100%;
      padding: 12px;
      background: var(--grad);
      color: #fff;
      font-weight: 700;
      font-size: 13.5px;
      border-radius: var(--radius-sm);
      display: flex;
      align-items: center;
      justify-content: center;
      gap: 8px;
      transition: all 0.25s var(--ease);
      box-shadow: var(--glow);
    }
    .quiz-next-btn:hover {
      transform: translateY(-2px);
      box-shadow: 0 10px 24px rgba(6,182,212,0.5);
    }

    /* Common Animations */
    @keyframes scaleIn {
      from { transform: scale(0.95); opacity: 0; }
      to { transform: scale(1); opacity: 1; }
    }
    @keyframes pulseCheck {
      0%, 100% { transform: scale(1); }
      50% { transform: scale(1.1); }
    }
    }

