body.script:
/**/
(function(){
  'use strict';
  var d=document,w=window;

  // robust image resizing helper
  function resizeBloggerImage(url, width, height) {
    if (!url) return '';
    if (url.indexOf('/s72-c/') !== -1) {
      return url.replace('/s72-c/', '/w' + width + '-h' + height + '-c/');
    }
    if (url.indexOf('=s72') !== -1) {
      return url.replace(/=s72.*/, '=w' + width + '-h' + height + '-c');
    }
    return url;
  }

  // preloader (disable delay for smoother mobile, fallback timeout for speed/SEO)
  var pre=d.getElementById('preloader');
  function hidePreloader(){if(pre&&!pre.classList.contains('done')){pre.classList.add('done');setTimeout(function(){pre.style.display='none'},500)}}
  w.addEventListener('load',hidePreloader);
  setTimeout(hidePreloader,3500); // 3.5s safety fallback

  // theme toggle
  var html=d.documentElement,tT=d.getElementById('themeToggle');
  tT&&tT.addEventListener('click',function(){
    var cur=html.getAttribute('data-theme')==='dark'?'light':'dark';
    if(cur==='dark') html.setAttribute('data-theme','dark'); else html.removeAttribute('data-theme');
    try{localStorage.setItem('techit-theme',cur)}catch(e){}
  });

  // mobile nav
  var menuBtn=d.getElementById('menuBtn'),nav=d.getElementById('mainNav'),bd=d.getElementById('navBackdrop');
  function closeNav(){nav&&nav.classList.remove('open');bd&&bd.classList.remove('open');d.body.style.overflow=''}
  menuBtn&&menuBtn.addEventListener('click',function(){nav&&nav.classList.toggle('open');bd&&bd.classList.toggle('open');if(nav)d.body.style.overflow=nav.classList.contains('open')?'hidden':''});
  bd&&bd.addEventListener('click',closeNav);
  if(nav){nav.querySelectorAll('li.has-sub > a').forEach(function(a){a.addEventListener('click',function(e){if(w.innerWidth<=860){e.preventDefault();a.parentNode.classList.toggle('open')}})})}

  // search
  var sBtn=d.getElementById('searchBtn'),ov=d.getElementById('searchOverlay'),sCl=d.getElementById('searchClose');
  sBtn&&sBtn.addEventListener('click',function(){ov.classList.add('open');var i=ov.querySelector('input');setTimeout(function(){i&&i.focus()},100)});
  sCl&&sCl.addEventListener('click',function(){ov.classList.remove('open')});
  ov&&ov.addEventListener('click',function(e){if(e.target===ov)ov.classList.remove('open')});
  d.addEventListener('keydown',function(e){if(e.key==='Escape'){ov&&ov.classList.remove('open');closeNav()}});

  // header shrink + progress + back to top
  var hm=d.getElementById('headerMain'),top=d.getElementById('toTop'),pr=d.getElementById('progress');
  w.addEventListener('scroll',function(){
    var y=w.scrollY||d.documentElement.scrollTop;
    hm&&(y>20?hm.classList.add('shrink'):hm.classList.remove('shrink'));
    top&&(y>500?top.classList.add('show'):top.classList.remove('show'));
    if(pr){var h=d.documentElement.scrollHeight-w.innerHeight;pr.style.width=(h>0?(y/h*100):0)+'%'}
  },{passive:true});
  top&&top.addEventListener('click',function(){w.scrollTo({top:0,behavior:'smooth'})});

  // reveal on scroll
  if('IntersectionObserver' in w){
    var io=new IntersectionObserver(function(en){en.forEach(function(x){if(x.isIntersecting){x.target.classList.add('in');io.unobserve(x.target)}})},{threshold:.12});
    d.querySelectorAll('.reveal').forEach(function(el){io.observe(el)});
  }else{d.querySelectorAll('.reveal').forEach(function(el){el.classList.add('in')})}

  // reading time + TOC (post only)
  var body=d.getElementById('postBody');
  if(body){
    var words=(body.innerText||'').trim().split(/\s+/).length;
    var mins=Math.max(1,Math.round(words/200));
    d.querySelectorAll('.read-min').forEach(function(e){e.textContent=mins});
    var hs=body.querySelectorAll('h2, h3'),toc=d.getElementById('toc'),list=d.getElementById('tocList');
    if(hs.length>=2&&toc&&list){
      hs.forEach(function(h,i){
        var id=h.id||('sec-'+i);h.id=id;
        var a=d.createElement('a');
        a.href='#'+id;
        a.setAttribute('data-toc-target',id);
        a.textContent=h.textContent;
        list.appendChild(a);
      });
      toc.style.display='block';
      toc.querySelector('.toc-head').addEventListener('click',function(){toc.classList.toggle('collapsed')});

      // smooth scroll + active highlight
      var updateActive=function(targetId){
        var links=list.querySelectorAll('a');
        links.forEach(function(l){
          if(l.getAttribute('data-toc-target')===targetId) l.classList.add('active');
          else l.classList.remove('active');
        });
      };

      list.querySelectorAll('a').forEach(function(a){
        a.addEventListener('click',function(e){
          e.preventDefault();
          var id=a.getAttribute('data-toc-target');
          var el=d.getElementById(id);
          if(!el) return;
          var headerH=(d.getElementById('headerMain')||{}).offsetHeight||74;
          var y=el.getBoundingClientRect().top + (w.scrollY||d.documentElement.scrollTop) - (headerH+16);
          w.scrollTo({top:y,behavior:'smooth'});
          updateActive(id);
        });
      });

      if('IntersectionObserver' in w){
        var obs=new IntersectionObserver(function(entries){
          var best=null;
          entries.forEach(function(ent){
            if(ent.isIntersecting){
              if(!best || ent.intersectionRatio>best.intersectionRatio) best=ent;
            }
          });
          if(best && best.target && best.target.id) updateActive(best.target.id);
        },{root:null,threshold:[0.15,0.25,0.4,0.6],rootMargin:'-90px 0px -70% 0px'});
        hs.forEach(function(h){obs.observe(h)});
      } else {
        w.addEventListener('scroll',function(){
          var headerH=(d.getElementById('headerMain')||{}).offsetHeight||74;
          var pos= (w.scrollY||d.documentElement.scrollTop) + headerH + 80;
          var currentId=null;
          hs.forEach(function(h){
            if(h.offsetTop<=pos) currentId=h.id;
          });
          if(currentId) updateActive(currentId);
        },{passive:true});
      }
    }

    var ptitle=(d.querySelector('.post-h1')||{}).textContent||'TechIT';
    body.querySelectorAll('img').forEach(function(img,n){
      if(!img.getAttribute('alt')||img.getAttribute('alt').trim()===''){img.setAttribute('alt',ptitle+(n>0?(' '+(n+1)):''))}
      if(!img.getAttribute('loading')){img.setAttribute('loading','lazy')}
    });

    var fqs=body.querySelectorAll('.faq-q');
    if(fqs.length){
      var faq=[];
      fqs.forEach(function(q){
        var a=q.nextElementSibling;
        if(a&&a.classList.contains('faq-a')){
          var det=d.createElement('details'),sum=d.createElement('summary');
          sum.className='faq-q';sum.innerHTML='<span>'+q.innerHTML+'</span><span class="fq-ic"><i class="fa-solid fa-plus"></i></span>';
          det.appendChild(sum);q.parentNode.insertBefore(det,q);det.appendChild(a);q.remove();
          faq.push({'@type':'Question','name':sum.textContent.trim(),'acceptedAnswer':{'@type':'Answer','text':a.textContent.trim()}});
        }
      });
      if(faq.length){
        var sc=d.createElement('script');sc.type='application/ld+json';
        sc.textContent=JSON.stringify({'@context':'https://schema.org','@type':'FAQPage','mainEntity':faq});
        d.head.appendChild(sc);
      }
    }
  }

  // Related Posts (label feed)
  var rw=d.getElementById('relatedWrap');
  if(rw){
    var lbl=rw.getAttribute('data-label'),home=(rw.getAttribute('data-home')||'/').replace(/\/$/,''),cur=rw.getAttribute('data-current');
    var grid=d.getElementById('relatedGrid'),ld=d.getElementById('relLoading');
    w.techitRelated=function(json){
      try{
        var ents=(json.feed.entry||[]),html='',count=0;
        for(var i=0;i<ents.length&&count<6;i++){
          var e=ents[i],url='';
          for(var k=0;k<e.link.length;k++){if(e.link[k].rel==='alternate'){url=e.link[k].href}}
          if(url===cur)continue;
          var title=e.title.$t,img='',cat=(e.category&&e.category[0])?e.category[0].term:'';
          if(e.media$thumbnail){img=resizeBloggerImage(e.media$thumbnail.url, 600, 338)}
          var thumb=img?('<img src="'+img+'" alt="'+title.replace(/"/g,'')+'" loading="lazy"/>'):('<img alt="TechIT" src="data:image/svg+xml;charset=UTF-8,%3Csvg xmlns=%22http://www.w3.org/2000/svg%22 width=%22600%22 height=%22338%22%3E%3Crect width=%22600%22 height=%22338%22 fill=%22%230d1b2a%22/%3E%3C/svg%3E"/>');
          html+='<article class="p-card"><a class="p-thumb" href="'+url+'">'+thumb+(cat?'<span class="p-label">'+cat+'</span>':'')+'</a><div class="p-body">'+(cat?'<span class="p-cat">'+cat+'</span>':'')+'<h3 class="p-title"><a href="'+url+'">'+title+'</a></h3><div class="p-foot"><div class="p-author"><span class="av">B</span><div><b>Banti Kevat</b></div></div><a class="arr" href="'+url+'"><i class="fa-solid fa-arrow-right"></i></a></div></div></article>';
          count++;
        }
        if(ld)ld.style.display='none';
        if(count){grid.innerHTML=html}else{rw.style.display='none'}
        if (w.techitOptimizeLinks) w.techitOptimizeLinks();
      }catch(err){rw.style.display='none'}
    };
    var s=d.createElement('script');
    s.src=home+'/feeds/posts/default/-/'+encodeURIComponent(lbl)+'?alt=json-in-script&max-results=7&callback=techitRelated';
    s.onerror=function(){rw.style.display='none'};
    d.body.appendChild(s);
  }

  // Web Stories strip (homepage, label: web-stories)
  var strip=d.getElementById('storiesStrip');
  if(strip){
    w.techitStories=function(json){
      try{
        var ents=(json.feed&&json.feed.entry)||[],html='';
        for(var i=0;i<ents.length&&i<10;i++){
          var e=ents[i],url='';
          for(var k=0;k<e.link.length;k++){if(e.link[k].rel==='alternate'){url=e.link[k].href}}
          var title=e.title.$t,img='';
          if(e.media$thumbnail){img=resizeBloggerImage(e.media$thumbnail.url, 300, 480)}
          html+='<a class="story-card" href="'+url+'">'+(img?'<img src="'+img+'" alt="'+title.replace(/"/g,'')+'" loading="lazy"/>':'')+'<span class="st-ov"></span><span class="st-ring"><i class="fa-solid fa-play"></i></span><span class="st-t">'+title+'</span></a>';
        }
        if(html){d.getElementById('storiesRow').innerHTML=html;strip.style.display='block'}
        if (w.techitOptimizeLinks) w.techitOptimizeLinks();
