      }
      searchTimeout = setTimeout(function() {
        var s = d.createElement('script');
        s.src = '/feeds/posts/default?alt=json-in-script&q=' + encodeURIComponent(q) + '&max-results=5&callback=techitAutocomplete';
        d.body.appendChild(s);
        s.onload = function() { s.remove(); };
        s.onerror = function() { s.remove(); };
      }, 300);
    });

    w.techitAutocomplete = function(json) {
      var entries = (json.feed && json.feed.entry) || [];
      if (!entries.length) {
        suggestionsBox.innerHTML = '<div style="padding:16px;text-align:center;color:var(--muted);font-size:14px;font-weight:500;">Koi results nahi mile...</div>';
        suggestionsBox.style.display = 'block';
