          try {
            date = new Date(e.published.$t).toLocaleDateString('hi-IN', { year: 'numeric', month: 'short', day: 'numeric' });
          } catch(err) {}
        }

        html += '<a class="suggestion-item" href="' + url + '">' + thumb + '<div class="s-info"><span class="s-title">' + title + '</span><span class="s-meta">' + date + '</span></div></a>';
      });
      suggestionsBox.innerHTML = html;
      suggestionsBox.style.display = 'block';
    };

