  // Fetch GitHub top projects
  function fetchGitHubProjects() {
    var ghList = d.getElementById('ghProjectsList');
    var ghLoading = d.getElementById('ghProjLoading');
    if (!ghList || !ghLoading) return;

    fetch('https://api.github.com/users/Bantikevat/repos?sort=updated&per_page=8')
      .then(function(res) { return res.json(); })
      .then(function(data) {
        if (!Array.isArray(data)) throw new Error('Invalid data');

        // Filter out forks and get top 4
        var repos = data.filter(function(repo) { return !repo.fork; }).slice(0, 4);

        if (repos.length === 0) {
          ghLoading.innerHTML = 'No public projects found.';
          return;
        }

        var html = '';
        repos.forEach(function(repo) {
          var desc = repo.description || 'No description provided.';
          if (desc.length > 70) desc = desc.substring(0, 67) + '...';

          var lang = repo.language || 'HTML';
          var langColors = {
            'JavaScript': '#f7df1e',
            'Python': '#3572A5',
            'HTML': '#e34f26',
            'CSS': '#563d7c',
            'TypeScript': '#3178c6',
            'Java': '#b07219',
            'C++': '#f34b7d'
          };
          var dotColor = langColors[lang] || '#8b5cf6';

          html += '<div class="gh-repo-card">' +
            '<div class="gh-repo-title">' +
              '<a href="' + repo.html_url + '" target="_blank" rel="noopener"><i class="fa-regular fa-folder-open"></i> ' + repo.name + '</a>' +
              (repo.stargazers_count > 0 ? '<span><i class="fa-regular fa-star"></i> ' + repo.stargazers_count + '</span>' : '') +
            '</div>' +
            '<p class="gh-repo-desc">' + desc + '</p>' +
            '<div class="gh-repo-meta">' +
              '<span><span class="gh-lang-dot" style="background:' + dotColor + '"></span> ' + lang + '</span>' +
              '<span><i class="fa-solid fa-code-branch"></i> ' + repo.forks_count + '</span>' +
            '</div>' +
          '</div>';
        });

        ghList.innerHTML = html;
        ghLoading.style.display = 'none';
        ghList.style.display = 'flex';
        if (w.techitOptimizeLinks) w.techitOptimizeLinks();
      })
      .catch(function(err) {
        console.error('Error loading GitHub projects:', err);
        ghLoading.innerHTML = '<span style="color:#ef4444">Failed to load projects.</span>';
      });
  }

  // Fetch HackerNews trending tech trends
  function fetchHackerNewsTrends() {
    var newsList = d.getElementById('newsList');
    var newsLoading = d.getElementById('newsLoading');
    if (!newsList || !newsLoading) return;

    fetch('https://hacker-news.firebaseio.com/v0/topstories.json')
      .then(function(res) { return res.json(); })
      .then(function(ids) {
        if (!Array.isArray(ids)) throw new Error('Invalid IDs');

        var topIds = ids.slice(0, 4);
        var fetchPromises = topIds.map(function(id) {
          return fetch('https://hacker-news.firebaseio.com/v0/item/' + id + '.json')
            .then(function(res) { return res.json(); });
        });

        return Promise.all(fetchPromises);
      })
      .then(function(stories) {
        var html = '';
        stories.forEach(function(story, index) {
          if (!story) return;
          var url = story.url || ('https://news.ycombinator.com/item?id=' + story.id);
          var title = story.title;
          if (title.length > 70) title = title.substring(0, 67) + '...';

          html += '<div class="news-item">' +
            '<span class="news-num">0' + (index + 1) + '</span>' +
            '<div class="news-details">' +
              '<h4 class="news-title"><a href="' + url + '" target="_blank" rel="noopener">' + title + '</a></h4>' +
              '<div class="news-meta">' +
                '<span>' + story.score + ' points</span> &#183; ' +
                '<span>by ' + story.by + '</span>' +
              '</div>' +
            '</div>' +
          '</div>';
        });

        newsList.innerHTML = html;
        newsLoading.style.display = 'none';
        newsList.style.display = 'flex';
        if (w.techitOptimizeLinks) w.techitOptimizeLinks();
      })
      .catch(function(err) {
        console.error('Error loading HackerNews trends:', err);
        newsLoading.innerHTML = '<span style="color:#ef4444">Failed to load trends.</span>';
      });
  }

