  // Live Geo-IP location greeting & Crypto rates ticker
  var topbarTicker = d.getElementById('topbarTicker');
  var tickerIcon = d.getElementById('tickerIcon');
  if (topbarTicker) {
    var tickerMessages = [
      "TechIT — Tech in Hindi | React · JavaScript · AI · Coding"
    ];
    var currentTickerIdx = 0;

    // Fetch Location (HTTPS, Free)
    fetch('https://ipwho.is/')
      .then(function(r) { return r.json(); })
      .then(function(data) {
        if (data && data.success && data.city) {
          var flag = data.country_flag ? data.country_flag : '📍';
          tickerMessages.push(flag + " Hello visitor from " + data.city + ", " + data.country + "! Swagat hai!");
        }
      }).catch(function() {});

    // Fetch Crypto Rates (using coincap.io which is CORS-friendly and free)
    var capUrl = 'https://api.coincap.io/v2/assets?ids=bitcoin,ethereum';
    fetch(capUrl)
      .then(function(r) { return r.json(); })
      .then(function(res) {
        if (res && res.data) {
          var usdToInr = 84.5; // Approximate conversion rate
          res.data.forEach(function(coin) {
            var priceUsd = parseFloat(coin.priceUsd);
            var priceInr = priceUsd * usdToInr;
            if (coin.id === 'bitcoin') {
              tickerMessages.push("🪙 BTC: $" + Math.round(priceUsd).toLocaleString() + " (₹" + Math.round(priceInr).toLocaleString() + ")");
            } else if (coin.id === 'ethereum') {
              tickerMessages.push("🪙 ETH: $" + Math.round(priceUsd).toLocaleString() + " (₹" + Math.round(priceInr).toLocaleString() + ")");
            }
          });
        }
      }).catch(function() {});

    // Rotator function
    setInterval(function() {
      if (tickerMessages.length <= 1) return;
      if (tickerIcon) {
        tickerIcon.classList.add('spin');
        setTimeout(function() { tickerIcon.classList.remove('spin'); }, 500);
      }
      topbarTicker.classList.add('fade-out');
      setTimeout(function() {
        currentTickerIdx = (currentTickerIdx + 1) % tickerMessages.length;
        topbarTicker.innerHTML = tickerMessages[currentTickerIdx];
        topbarTicker.classList.remove('fade-out');
        topbarTicker.classList.add('fade-in');
        setTimeout(function() { topbarTicker.classList.remove('fade-in'); }, 400);
      }, 400);
    }, 6000);
  }

  // Live Coder Humor Fetch with offline fallbacks and timeout
  function fetchCoderJoke() {
    var jBody = d.getElementById('jokeBody');
    var jSpinner = d.getElementById('jokeSpinner');
    if (!jBody) return;

    if (jSpinner) jSpinner.classList.add('fa-spin');

    var fallbackJokes = [
      "Why do programmers wear glasses? Because they can't C#!",
      "There are 10 types of people in the world: those who understand binary, and those who don't.",
      "How many programmers does it take to change a light bulb? None, that's a hardware problem!",
      "A SQL query goes into a bar, walks up to two tables and asks, 'Can I join you?'",
      "What is a programmer's favorite hangout place? Foo Bar!",
      "An optimist says the glass is half full. A pessimist says the glass is half empty. A programmer says the glass is twice as large as necessary!"
    ];

    var controller = new AbortController();
    var signal = controller.signal;
    var timeoutId = setTimeout(function() {
      controller.abort();
    }, 3000); // 3 seconds timeout

    fetch('https://v2.jokeapi.dev/joke/Programming?safe-mode', { signal: signal })
      .then(function(r) { return r.json(); })
      .then(function(data) {
        clearTimeout(timeoutId);
        if (jSpinner) jSpinner.classList.remove('fa-spin');
        if (data.type === 'single') {
          jBody.textContent = data.joke;
        } else if (data.type === 'twopart') {
          jBody.innerHTML = '<strong>Q:</strong> ' + data.setup + '<br/><br/><strong>A:</strong> ' + data.delivery;
        }
      })
      .catch(function() {
        clearTimeout(timeoutId);
        if (jSpinner) jSpinner.classList.remove('fa-spin');
        var randomJoke = fallbackJokes[Math.floor(Math.random() * fallbackJokes.length)];
        jBody.textContent = randomJoke;
      });
  }

  var jRefresh = d.getElementById('jokeRefresh');
