    jRefresh.addEventListener('click', fetchCoderJoke);
    fetchCoderJoke();
  }

  // --- Text-To-Speech (TTS) Engine ---
  var ttsPlayBtn = d.getElementById('ttsPlayBtn');
  var ttsStopBtn = d.getElementById('ttsStopBtn');
  var ttsSpeedBtn = d.getElementById('ttsSpeedBtn');
  var ttsSpeedDropdown = d.getElementById('ttsSpeedDropdown');
  var ttsStatusText = d.getElementById('ttsStatusText');
  var ttsProgressBar = d.getElementById('ttsProgressBar');
  var ttsProgressContainer = d.getElementById('ttsProgressContainer');
  var ttsPlayIcon = d.getElementById('ttsPlayIcon');
  var ttsPulseIcon = d.querySelector('.tts-pulse');

  if (ttsPlayBtn && ttsStopBtn) {
    var synth = w.speechSynthesis;
    var sentences = [];
    var currentSentenceIdx = 0;
    var utteranceRate = 1.0;
    var activeUtterance = null;
    var isReading = false;
    var isPausedState = false;

    // Toggle Speed Dropdown
    if (ttsSpeedBtn && ttsSpeedDropdown) {
      ttsSpeedBtn.addEventListener('click', function(e) {
        e.stopPropagation();
        ttsSpeedDropdown.classList.toggle('open');
      });
      d.addEventListener('click', function() {
        ttsSpeedDropdown.classList.remove('open');
      });
      ttsSpeedDropdown.querySelectorAll('span').forEach(function(item) {
        item.addEventListener('click', function() {
          ttsSpeedDropdown.querySelectorAll('span').forEach(function(s) { s.classList.remove('active'); });
          item.classList.add('active');
          var speed = parseFloat(item.getAttribute('data-speed'));
          utteranceRate = speed;
          ttsSpeedBtn.textContent = speed + 'x';

          if (isReading) {
            // Restart from current sentence to apply rate change immediately
            synth.cancel();
            speakSentence(currentSentenceIdx);
          }
        });
      });
    }

    function cleanTextForSpeech() {
      var body = d.getElementById('postBody');
      if (!body) return [];

      // Clone body to manipulate without breaking the page
      var clone = body.cloneNode(true);

      // Remove all elements we shouldn't read
      clone.querySelectorAll('pre, code, table, .ad-zone, .share-box, .author-box, script, style, blockquote footer').forEach(function(el) {
        el.remove();
      });

      // Extract text content from headings and paragraphs
      var elements = clone.querySelectorAll('h2, h3, h4, p, blockquote');
      var rawText = '';
      elements.forEach(function(el) {
        rawText += el.textContent.trim() + '. ';
      });

      // Clean up whitespace
      rawText = rawText.replace(/\s+/g, ' ').trim();

      // Split into sentences using regex (split by periods, question marks, exclamation marks followed by spaces)
      var splitArr = rawText.split(/[.!?]+(?=\s|$)/);
      var result = [];
      splitArr.forEach(function(s) {
        var cleanStr = s.trim();
        if (cleanStr.length > 5) {
          result.push(cleanStr);
        }
      });
      return result;
    }

    function updateProgress() {
      if (sentences.length === 0) return;
      var percent = ((currentSentenceIdx) / sentences.length) * 100;
      ttsProgressBar.style.width = percent + '%';
    }

    function selectVoice(voices) {
      // Priority 1: Hindi voice
      for (var i = 0; i < voices.length; i++) {
        var lang = voices[i].lang.toLowerCase();
        if (lang === 'hi-in' || lang.indexOf('hi_in') !== -1 || lang.indexOf('hindi') !== -1) {
          return voices[i];
        }
      }
      // Priority 2: Indian English accent
      for (var i = 0; i < voices.length; i++) {
        var lang = voices[i].lang.toLowerCase();
        if (lang === 'en-in' || lang.indexOf('en_in') !== -1 || voices[i].name.toLowerCase().indexOf('india') !== -1) {
          return voices[i];
        }
      }
      // Priority 3: English US/GB
      for (var i = 0; i < voices.length; i++) {
        var lang = voices[i].lang.toLowerCase();
        if (lang === 'en-us' || lang === 'en-gb') {
          return voices[i];
        }
      }
      return null;
    }

    function speakSentence(index) {
      if (index >= sentences.length) {
        stopReading();
        return;
      }
      currentSentenceIdx = index;
      updateProgress();

      var text = sentences[index];
      activeUtterance = new SpeechSynthesisUtterance(text);
      activeUtterance.rate = utteranceRate;

      var voices = synth.getVoices();
      var selectedVoice = selectVoice(voices);
      if (selectedVoice) {
        activeUtterance.voice = selectedVoice;
      }

      activeUtterance.onend = function() {
        if (isReading && !isPausedState) {
          speakSentence(currentSentenceIdx + 1);
        }
      };

      activeUtterance.onerror = function() {
        if (isReading && !isPausedState) {
          speakSentence(currentSentenceIdx + 1);
        }
      };

      synth.speak(activeUtterance);
    }

    function startReading() {
      sentences = cleanTextForSpeech();
      if (sentences.length === 0) {
        ttsStatusText.textContent = "No readable text found.";
        return;
      }
      isReading = true;
      isPausedState = false;
      currentSentenceIdx = 0;

      ttsStopBtn.style.display = 'inline-flex';
      d.getElementById('ttsSpeedSelector').style.display = 'inline-flex';
      ttsProgressContainer.style.display = 'block';
      ttsPulseIcon.classList.add('active');

      ttsPlayIcon.className = 'fa-solid fa-pause';
      ttsPlayBtn.innerHTML = '<i class="fa-solid fa-pause" id="ttsPlayIcon"></i> Pause';
      ttsStatusText.textContent = "Reading article aloud...";

      synth.cancel(); // clear queue
      speakSentence(0);
    }

    function pauseReading() {
      isPausedState = true;
      synth.pause();
      ttsPulseIcon.classList.remove('active');
      ttsPlayIcon.className = 'fa-solid fa-play';
      ttsPlayBtn.innerHTML = '<i class="fa-solid fa-play" id="ttsPlayIcon"></i> Resume';
      ttsStatusText.textContent = "Audio Paused";
    }

    function resumeReading() {
      isPausedState = false;
      ttsPulseIcon.classList.add('active');
      ttsPlayIcon.className = 'fa-solid fa-pause';
      ttsPlayBtn.innerHTML = '<i class="fa-solid fa-pause" id="ttsPlayIcon"></i> Pause';
      ttsStatusText.textContent = "Reading article aloud...";

      if (synth.paused) {
        synth.resume();
      } else {
        synth.cancel();
        speakSentence(currentSentenceIdx);
      }
    }

    function stopReading() {
      isReading = false;
      isPausedState = false;
      synth.cancel();

      ttsStopBtn.style.display = 'none';
      d.getElementById('ttsSpeedSelector').style.display = 'none';
      ttsProgressContainer.style.display = 'none';
      ttsPulseIcon.classList.remove('active');

      ttsPlayIcon.className = 'fa-solid fa-play';
      ttsPlayBtn.innerHTML = '<i class="fa-solid fa-play" id="ttsPlayIcon"></i> Listen';
      ttsStatusText.textContent = "Listen to this article (Hindi/English)";
      ttsProgressBar.style.width = '0%';
    }

    ttsPlayBtn.addEventListener('click', function() {
      if (!isReading) {
        startReading();
      } else if (isPausedState) {
        resumeReading();
      } else {
        pauseReading();
      }
    });

    ttsStopBtn.addEventListener('click', stopReading);

    // Stop speaking when user leaves page
    w.addEventListener('beforeunload', function() {
      synth.cancel();
    });
  }



  // --- TechIT Command Center Spotlight Search Engine ---
  (function() {
    d.addEventListener('DOMContentLoaded', function() {
      var overlay = d.getElementById('cmdOverlay');
    var trigger = d.getElementById('cmdTriggerBtn');
    var input = d.getElementById('cmdInput');
    var results = d.getElementById('cmdResults');
    var closeBtn = d.getElementById('cmdCloseBtn');

    if (!overlay || !input || !results) return;

    var postEntries = [];
    var activeIdx = -1;

    // Default static actions / commands
    var commands = [
      { type: 'command', title: 'Toggle Dark Mode', cmd: '> dark', icon: 'fa-regular fa-moon', badge: 'CMD' },
      { type: 'command', title: 'Toggle Light Mode', cmd: '> light', icon: 'fa-regular fa-sun', badge: 'CMD' },
      { type: 'command', title: 'Read Article Aloud (Text-to-Speech)', cmd: '> listen', icon: 'fa-solid fa-headphones-simple', badge: 'CMD' },
      { type: 'command', title: 'Show Random Tech Quote', cmd: '> quote', icon: 'fa-solid fa-quote-left', badge: 'CMD' },
      { type: 'command', title: 'Open GitHub Profile', cmd: '> github', icon: 'fa-brands fa-github', badge: 'URL' },
      { type: 'command', title: 'View Blog Site Map', cmd: '> sitemap', icon: 'fa-solid fa-sitemap', badge: 'URL' }
    ];

    // Preload posts from Blogger Atom/JSON feed
    function preloadPosts() {
      if (postEntries.length > 0) return;
      fetch('/feeds/posts/default?alt=json&max-results=80')
        .then(function(res) { return res.json(); })
        .then(function(data) {
          if (data.feed && data.feed.entry) {
            postEntries = data.feed.entry.map(function(entry) {
              var link = '';
              for (var i = 0; i < entry.link.length; i++) {
                if (entry.link[i].rel === 'alternate') {
                  link = entry.link[i].href;
                  break;
                }
              }
              return {
                type: 'post',
                title: entry.title.$t,
                url: link,
                icon: 'fa-regular fa-file-lines',
                badge: 'POST'
              };
            });
            if (overlay.classList.contains('open')) {
              renderResults();
            }
          }
        })
        .catch(function(err) {
          console.error('Error preloading command center feeds:', err);
        });
    }

    function openCommandCenter() {
      overlay.classList.add('open');
      d.body.style.overflow = 'hidden';
      preloadPosts();
      setTimeout(function() { input.focus(); }, 150);
      renderResults();
    }

    function closeCommandCenter() {
      overlay.classList.remove('open');
      d.body.style.overflow = '';
      input.value = '';
      activeIdx = -1;
    }

    function executeCommand(item) {
      if (!item) return;

      if (item.type === 'post') {
        w.location.href = item.url;
        closeCommandCenter();
        return;
      }

      // Commands execution
      if (item.cmd === '> dark') {
        d.documentElement.setAttribute('data-theme', 'dark');
        try { localStorage.setItem('techit-theme', 'dark'); } catch(e) {}
        closeCommandCenter();
      } else if (item.cmd === '> light') {
        d.documentElement.removeAttribute('data-theme');
        try { localStorage.setItem('techit-theme', 'light'); } catch(e) {}
        closeCommandCenter();
      } else if (item.cmd === '> listen') {
        closeCommandCenter();
        var playBtn = d.getElementById('ttsPlayBtn');
        if (playBtn) playBtn.click();
      } else if (item.cmd === '> quote') {
        closeCommandCenter();
        var qBtn = d.getElementById('HTML98');
        if (qBtn) {
          qBtn.scrollIntoView({ behavior: 'smooth' });
          qBtn.style.outline = '2px solid #06b6d4';
          setTimeout(function() { qBtn.style.outline = 'none'; }, 2000);
        }
      } else if (item.cmd === '> github') {
        w.open('https://github.com/Bantikevat', '_blank');
        closeCommandCenter();
      } else if (item.cmd === '> sitemap') {
        w.location.href = '/p/blog-page.html';
        closeCommandCenter();
      }
    }

    function renderResults() {
      var val = input.value.trim().toLowerCase();
      var html = '';
      var list = [];

      if (val.indexOf('>') === 0) {
        var cmdQuery = val.substring(1).trim();
        list = commands.filter(function(c) {
          return c.title.toLowerCase().includes(cmdQuery) || c.cmd.includes(cmdQuery);
        });

        html += '<div class="cmd-group-title">Commands</div>';
        if (list.length === 0) {
          html += '<div style="padding: 12px 14px; font-size:13px; color:#64748b;">No matching commands found.</div>';
        }
      } else if (val === '') {
        html += '<div class="cmd-group-title">Quick Commands</div>';
        commands.forEach(function(c) {
          list.push(c);
        });

        if (postEntries.length > 0) {
          html += '<div class="cmd-group-title">Recent Articles</div>';
          postEntries.slice(0, 5).forEach(function(p) {
            list.push(p);
          });
        }
      } else {
        list = postEntries.filter(function(p) {
          return p.title.toLowerCase().indexOf(val) !== -1;
        });

        html += '<div class="cmd-group-title">Search Results (' + list.length + ')</div>';
        if (list.length === 0) {
          html += '<div style="padding: 12px 14px; font-size:13px; color:#64748b;">No articles found for "' + val + '".</div>';
        }
      }

      list.forEach(function(item, idx) {
        var isActive = idx === activeIdx;
        var activeClass = isActive ? ' active' : '';

        html += '<div class="cmd-item' + activeClass + '" data-index="' + idx + '">' +
          '<i class="' + item.icon + ' cmd-item-icon"></i>' +
          '<span class="cmd-item-text">' + item.title + '</span>' +
          '<span class="cmd-item-badge">' + item.badge + '</span>' +
        '</div>';
      });

      results.innerHTML = html;

      results.querySelectorAll('.cmd-item').forEach(function(el) {
        el.addEventListener('click', function() {
          var idx = parseInt(el.getAttribute('data-index'), 10);
          executeCommand(list[idx]);
        });
      });

      overlay.currentList = list;
    }

    input.addEventListener('input', function() {
      activeIdx = -1;
      renderResults();
    });

    d.addEventListener('keydown', function(e) {
      if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 'k') {
        e.preventDefault();
        if (overlay.classList.contains('open')) {
          closeCommandCenter();
        } else {
          openCommandCenter();
        }
        return;
      }

      if (!overlay.classList.contains('open')) return;

      var list = overlay.currentList || [];
      if (list.length === 0) return;

      if (e.key === 'Escape') {
        e.preventDefault();
        closeCommandCenter();
      } else if (e.key === 'ArrowDown') {
        e.preventDefault();
        activeIdx = (activeIdx + 1) % list.length;
        renderResults();
        scrollToActiveItem();
      } else if (e.key === 'ArrowUp') {
        e.preventDefault();
        activeIdx = (activeIdx - 1 + list.length) % list.length;
        renderResults();
        scrollToActiveItem();
      } else if (e.key === 'Enter') {
        e.preventDefault();
        if (activeIdx >= 0 && activeIdx < list.length) {
          executeCommand(list[activeIdx]);
        }
      }
    });

    function scrollToActiveItem() {
      var activeEl = results.querySelector('.cmd-item.active');
      if (activeEl) {
        activeEl.scrollIntoView({ block: 'nearest' });
      }
    }

    trigger && trigger.addEventListener('click', function(e) {
      e.stopPropagation();
      openCommandCenter();
    });
      closeBtn && closeBtn.addEventListener('click', closeCommandCenter);
      overlay.addEventListener('click', function(e) {
        if (e.target === overlay) closeCommandCenter();
      });
    });
  })();

  // --- TechIT Premium 3D Tilt & Parallax Glare Engine (Dynamic Delegation) ---
  (function() {
    if (w.matchMedia('(hover: hover)').matches) {
      d.addEventListener('mouseenter', function(e) {
        var card = e.target.closest && e.target.closest('.p-card, .s-card, .gh-repo-card, .trending-item');
        if (!card) return;
        if (card.dataset.tiltInitialized) return;
        card.dataset.tiltInitialized = 'true';

        // Create glare element
        var glare = card.querySelector('.card-glare');
        if (!glare) {
          glare = d.createElement('div');
          glare.className = 'card-glare';
          glare.style.position = 'absolute';
          glare.style.inset = '0';
          glare.style.pointerEvents = 'none';
          glare.style.borderRadius = 'inherit';
          glare.style.zIndex = '5';
          glare.style.background = 'radial-gradient(circle at 50% 50%, rgba(6, 182, 212, 0), transparent 50%)';
          glare.style.transition = 'background 0.3s';
          card.appendChild(glare);
        }

        card.addEventListener('mousemove', function(ev) {
          var rect = card.getBoundingClientRect();
          var x = ev.clientX - rect.left;
          var y = ev.clientY - rect.top;

          var centerX = rect.width / 2;
          var centerY = rect.height / 2;

          var tiltX = (centerY - y) / centerY * 6; 
          var tiltY = (x - centerX) / centerX * 6;

          card.style.transform = 'rotateX(' + tiltX.toFixed(2) + 'deg) rotateY(' + tiltY.toFixed(2) + 'deg) scale3d(1.02, 1.02, 1.02)';

          var glareX = (x / rect.width * 100).toFixed(1);
          var glareY = (y / rect.height * 100).toFixed(1);
          glare.style.background = 'radial-gradient(circle at ' + glareX + '% ' + glareY + '%, rgba(6, 182, 212, 0.1), transparent 60%)';
        }, { passive: true });

        card.addEventListener('mouseleave', function() {
          card.style.transform = 'rotateX(0deg) rotateY(0deg) scale3d(1, 1, 1)';
          glare.style.background = 'radial-gradient(circle at 50% 50%, rgba(6, 182, 212, 0), transparent 50%)';
        });
      }, true);
    }
  })();

  // --- SEO link optimizer: external links nofollow + target blank ---
  function optimizeExternalLinks() {
    d.querySelectorAll('a').forEach(function(a) {
      if (a.href && a.host !== w.location.host && !a.href.startsWith('javascript:') && !a.href.startsWith('#')) {
        var isTrusted = /github\.com|linkedin\.com|instagram\.com|twitter\.com|x\.com|t\.me|blogspot\.com/.test(a.href);
        var rel = isTrusted ? 'noopener noreferrer' : 'nofollow noopener noreferrer';
        a.setAttribute('rel', rel);
        a.setAttribute('target', '_blank');
      }
    });
  }
  // Run on page load
  w.addEventListener('load', optimizeExternalLinks);
  w.techitOptimizeLinks = optimizeExternalLinks;

  // --- Lightweight Hover Link Preloader for Core Web Vitals speed ---
  if ('requestIdleCallback' in w) {
    var prefetchedUrls = new Set();
    d.addEventListener('mouseover', function(e) {
      var a = e.target.closest && e.target.closest('a');
      if (a && a.href && a.host === w.location.host && !prefetchedUrls.has(a.href) && !a.hash && !a.href.startsWith('javascript:')) {
        prefetchedUrls.add(a.href);
        w.requestIdleCallback(function() {
          var link = d.createElement('link');
          link.rel = 'prefetch';
          link.href = a.href;
          d.head.appendChild(link);
        });
      }
    }, { passive: true });
  }

  // --- Dynamic AdSense Lazy Loader for Core Web Vitals speed ---
  (function() {
    var adsLoaded = false;
    function loadAdSense() {
      if (adsLoaded) return;
      adsLoaded = true;

      w.removeEventListener('scroll', loadAdSense);
      w.removeEventListener('mousemove', loadAdSense);
      w.removeEventListener('touchstart', loadAdSense);

      var s = d.createElement('script');
      s.async = true;
      s.crossOrigin = 'anonymous';
      s.src = 'https://pagead2.googlesyndication.com/pagead/js/adsbygoogle.js?client=ca-pub-6313655718513585';
      d.head.appendChild(s);
    }
    w.addEventListener('scroll', loadAdSense, { passive: true });
    w.addEventListener('mousemove', loadAdSense, { passive: true });
    w.addEventListener('touchstart', loadAdSense, { passive: true });
    setTimeout(loadAdSense, 4000);
  })();

  // --- Smooth comments scroll helper ---
  var commLink = d.querySelector('.pm-comments-link');
  if (commLink) {
    commLink.addEventListener('click', function(e) {
      e.preventDefault();
      var commSection = d.getElementById('comments') || d.querySelector('.comments');
      if (commSection) {
        var headerH = (d.getElementById('headerMain') || {}).offsetHeight || 74;
        var y = commSection.getBoundingClientRect().top + (w.scrollY || d.documentElement.scrollTop) - (headerH + 16);
        w.scrollTo({ top: y, behavior: 'smooth' });
      }
    });
  }

  // --- Helpful Post Feedback Handler ---
  var fbWidget = d.getElementById('feedbackWidget');
  if (fbWidget) {
    var postId = fbWidget.getAttribute('data-post-id');
    var storageKey = 'techit-fb-' + postId;
    var fbMain = d.getElementById('fbMainZone');
    var fbThanks = d.getElementById('fbThanksZone');

    // Check if voted already
    var voted = false;
    try { voted = localStorage.getItem(storageKey); } catch(e) {}
    if (voted) {
      if (fbMain) fbMain.style.display = 'none';
      if (fbThanks) fbThanks.style.display = 'block';
    } else {
      fbWidget.querySelectorAll('.fb-btn').forEach(function(btn) {
        btn.addEventListener('click', function() {
          var val = btn.getAttribute('data-value');
          try { localStorage.setItem(storageKey, val); } catch(e) {}
          if (fbMain) fbMain.style.display = 'none';
          if (fbThanks) {
            fbThanks.style.display = 'block';
            fbThanks.style.animation = 'scaleIn 0.3s var(--ease)';
          }
        });
      });
    }
  }

  // --- Medium-Style Highlight Share Tooltip ---
  (function() {
    var postBody = d.getElementById('postBody');
    if (!postBody) return;

    var tooltip = d.createElement('div');
    tooltip.className = 'share-tooltip';
    tooltip.innerHTML = 
      '<button class="share-tooltip-btn tt-copy" type="button"><i class="fa-regular fa-copy"></i> Copy</button>' +
      '<button class="share-tooltip-btn tt-tweet" type="button"><i class="fa-brands fa-x-twitter"></i> Tweet</button>';
    d.body.appendChild(tooltip);

    var selectedText = '';

    function checkSelection() {
      var sel = w.getSelection();
      var txt = sel.toString().trim();
      if (txt.length < 5 || !postBody.contains(sel.anchorNode)) {
        tooltip.classList.remove('show');
        return;
      }

      selectedText = txt;
      var range = sel.getRangeAt(0);
      var rect = range.getBoundingClientRect();

      var scrollX = w.scrollX || d.documentElement.scrollLeft;
      var scrollY = w.scrollY || d.documentElement.scrollTop;

      var top = rect.top + scrollY - tooltip.offsetHeight - 10;
      var left = rect.left + scrollX + (rect.width / 2) - (tooltip.offsetWidth / 2);

      tooltip.style.top = top + 'px';
      tooltip.style.left = left + 'px';
      tooltip.classList.add('show');
    }

    d.addEventListener('mouseup', function() {
      setTimeout(checkSelection, 10);
    });
    d.addEventListener('keyup', function() {
      setTimeout(checkSelection, 10);
    });
    d.addEventListener('mousedown', function(e) {
      if (!tooltip.contains(e.target)) {
        tooltip.classList.remove('show');
      }
    });

    tooltip.querySelector('.tt-copy').addEventListener('click', function() {
      navigator.clipboard.writeText(selectedText).then(function() {
        var btn = tooltip.querySelector('.tt-copy');
        btn.innerHTML = '<i class="fa-solid fa-check" style="color:#22c55e"></i> Copied!';
        setTimeout(function() {
          btn.innerHTML = '<i class="fa-regular fa-copy"></i> Copy';
          tooltip.classList.remove('show');
        }, 1200);
      });
    });

    tooltip.querySelector('.tt-tweet').addEventListener('click', function() {
      var tweetUrl = 'https://twitter.com/intent/tweet?text=' + encodeURIComponent('"' + selectedText + '"') + '&url=' + encodeURIComponent(w.location.href);
      w.open(tweetUrl, '_blank', 'width=550,height=420');
      tooltip.classList.remove('show');
    });
  })();

  // --- Interactive Coding Quiz Engine ---
  (function() {
    var quizQ = d.getElementById('quizQuestion');
    var quizOpts = d.getElementById('quizOptions');
    var quizExpl = d.getElementById('quizExplanation');
    var nextBtn = d.getElementById('quizNextBtn');
    if (!quizQ || !quizOpts || !quizExpl || !nextBtn) return;

    var quizPool = [
      {
        q: "JavaScript mein 'typeof null' kya return karta hai?",
        opts: ["'null'", "'undefined'", "'object'", "'number'"],
        correct: 2,
        expl: "Javascript default design choice ki wajah se 'typeof null' return karta hai 'object'. Yeh ek purana bug hai jo compatibility ke liye kabhi change nahi kiya gaya."
      },
      {
        q: "React Hooks rules ke mutabik Hooks kahan call hone chahiye?",
        opts: ["Har condition/loops ke andar", "Keval functional components ke top level par", "Regular functions ke andar", "Class components ke constructor mein"],
        correct: 1,
        expl: "Hooks ko hamesha react functional component ke topmost level par hi call karna chahiye. Hooks loop, conditionals, ya nested functions ke andar call nahi hone chahiye."
      },
      {
        q: "Konsa variable definition scope global/function boundary cross nahi karta hai?",
        opts: ["var", "let", "global", "scope"],
        correct: 1,
        expl: "'let' aur 'const' blocks-scoped variables hote hain jo keval unke surrounding block {} ke andar hi accessible hote hain, jabki 'var' function-scoped hota hai."
      },
      {
        q: "JavaScript array method 'map()' aur 'forEach()' mein main difference kya hai?",
        opts: ["map fast hota hai", "forEach array return karta hai", "map ek naya array return karta hai, forEach return nahi karta", "koi difference nahi hai"],
        correct: 2,
        expl: "'map()' call array ke elements ko transform karke naya array return karta hai, jabki 'forEach()' arrays ke elements par loop chalata hai par koi value return nahi karta."
      },
      {
        q: "CSS Flexbox property 'align-items' kis cross axis par justify karti hai?",
        opts: ["Vertical cross axis", "Horizontal main axis", "Flex direction wrap axis", "None"],
        correct: 0,
        expl: "'justify-content' inline (main-axis) align karta hai, aur 'align-items' content elements ko vertical cross-axis par align karti hai."
      },
      {
        q: "JavaScript Object representation 'JSON' ka full form kya hai?",
        opts: ["Java Simple Object Notation", "JavaScript Object Notation", "JavaScript Online Node", "None of these"],
        correct: 1,
        expl: "JSON ka matlab hai JavaScript Object Notation, yeh lightweight structure data exchange format hai jo human readable hai."
      }
    ];

    var activeQIndex = 0;

    function loadQuestion() {
      var index = Math.floor(Math.random() * quizPool.length);
      activeQIndex = index;

      var data = quizPool[index];
      quizQ.textContent = data.q;
      quizExpl.style.display = 'none';
      nextBtn.style.display = 'none';

      quizOpts.innerHTML = '';
      data.opts.forEach(function(optText, idx) {
        var btn = d.createElement('button');
        btn.className = 'quiz-opt';
        btn.type = 'button';
        btn.innerHTML = '<span class="quiz-opt-dot"></span> ' + optText;
        btn.addEventListener('click', function() {
          selectOption(idx);
        });
        quizOpts.appendChild(btn);
      });
    }

    function selectOption(selectedIdx) {
      var data = quizPool[activeQIndex];
      var buttons = quizOpts.querySelectorAll('.quiz-opt');

      buttons.forEach(function(btn, idx) {
        btn.disabled = true;
        if (idx === data.correct) {
          btn.classList.add('correct');
        } else if (idx === selectedIdx) {
          btn.classList.add('incorrect');
        }
      });

      quizExpl.textContent = data.expl;
      quizExpl.style.display = 'block';
      quizExpl.style.animation = 'slideDown 0.3s var(--ease)';
      nextBtn.style.display = 'flex';
    }

    nextBtn.addEventListener('click', function() {
      var nextIcon = nextBtn.querySelector('i');
      if (nextIcon) {
        nextIcon.classList.add('fa-spin');
        setTimeout(function() {
          nextIcon.classList.remove('fa-spin');
          loadQuestion();
        }, 400);
      } else {
        loadQuestion();
      }
    });

    loadQuestion();
  })();

  // --- Lazy-Load Prism.js Syntax Highlighter on Demand ---
  (function() {
    var preBlocks = d.querySelectorAll('.post-content pre');
    if (preBlocks.length > 0) {
      // 1. Auto-detect and add language-javascript class if code has no class
      preBlocks.forEach(function(pre) {
        var code = pre.querySelector('code');
        if (code && !code.className) {
          code.className = 'language-javascript';
        }
        // Ensure pre block has a language class for Prism styling to apply cleanly
        if (!pre.className || !pre.className.match(/language-/)) {
          pre.className = (pre.className ? pre.className + ' ' : '') + (code ? code.className : 'language-javascript');
        }
      });

      // 2. Load Prism Tomorrow CSS stylesheet
      var css = d.createElement('link');
      css.rel = 'stylesheet';
      css.href = 'https://cdnjs.cloudflare.com/ajax/libs/prism/1.29.0/themes/prism-tomorrow.min.css';
      d.head.appendChild(css);

      // 3. Load main Prism core JS
      var js = d.createElement('script');
      js.src = 'https://cdnjs.cloudflare.com/ajax/libs/prism/1.29.0/components/prism-core.min.js';
      js.defer = true;
      js.onload = function() {
        // 4. Load required languages dynamically
        var langs = ['markup', 'css', 'clike', 'javascript', 'jsx'];
        var loadedCount = 0;

        langs.forEach(function(lang) {
          var s = d.createElement('script');
          s.src = 'https://cdnjs.cloudflare.com/ajax/libs/prism/1.29.0/components/prism-' + lang + '.min.js';
          s.defer = true;
          s.onload = function() {
            loadedCount++;
            if (loadedCount === langs.length && w.Prism) {
              w.Prism.highlightAll();
            }
          };
          d.body.appendChild(s);
        });
      };
      d.body.appendChild(js);
    }
  })();

})();
